window.STORYSPROUT_BOOKS[6]={"number":6,"title":"Super Minds 6","edition":"Cambridge University Press · 所上传学生用书扫描版","sourceNote":"依据所上传的 Super Minds 6 学生用书，覆盖导入单元及 9 个正式单元。故事与阅读卡为标明页码的分段教学改写，题目、例句与表达支架为新编；完整原页可对照查看。没有提供第六册教师用书或原版音频，不把听力空格推测成标准答案。旧版材料的交通统计、开放时间与预测不作今日事实使用；冒险情节是虚构故事，不是现实操作指导。","bookSummary":"跟随 Alex、Phoebe 和 Patrick 穿越时空，把长故事拆成因果线索；学会解释、比较、转述和提出假设。","storyGuide":"返校实验 → 海盗宝藏 → 未来交通 → 古埃及 → 奥运赛场 → 伦敦大火 → 发明实验室 → 休斯敦 → 冰雪世界 → 恐龙追逐与归来","teacherAvailable":false,"pageMin":2,"pageMax":127,"pageBase":"books/6/pages","grammarAppendix":true,"units":[{"id":0,"title":"Back to school","zh":"重返学校","start":4,"end":9,"icon":"🏫","goal":"按原因与结果复述实验事故，区分“已经”和“还没有”。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":118,"vocab":[{"word":"basketball hoop","zh":"篮球架上的篮圈","example":"The basketball hoop is above the net."},{"word":"tennis court","zh":"网球场","example":"We meet beside the tennis court."},{"word":"net","zh":"网；球网","example":"The ball went over the net."},{"word":"football pitch","zh":"足球场","example":"The football pitch is behind our school."},{"word":"railings","zh":"栏杆","example":"Please stay inside the railings."},{"word":"running track","zh":"跑道","example":"We walked around the running track."},{"word":"bike rack","zh":"自行车停放架","example":"My bike is in the bike rack."},{"word":"litter bin","zh":"垃圾桶","example":"Put the paper in the litter bin."},{"word":"school bell","zh":"学校的铃","example":"The school bell has already rung."}],"grammar":[{"title":"already / yet：已经与尚未","rule":"现在完成时：have / has + 过去分词。already 通常在肯定句中，yet 常放在否定句或问句末尾。","examples":[{"en":"I have already packed my bag.","zh":"我已经收拾好书包了。"},{"en":"She has not finished the experiment yet.","zh":"她还没有完成实验。"}],"questions":[{"prompt":"I have ___ read the instructions.","options":["already","yet","tomorrow"],"answer":0,"why":"肯定句表示“已经读过”，用 already。","kind":"grammar","id":"u0-g0-q0"},{"prompt":"Has Patrick put on his goggles ___?","options":["already yesterday","yet","ago"],"answer":1,"why":"问“已经戴好了吗”，yet 放在疑问句末尾。","kind":"grammar","id":"u0-g0-q1"}]},{"title":"who / which / where：补充说明","rule":"who 介绍人，which 介绍物；where 介绍事情发生的地点。先找被说明的名词。","examples":[{"en":"Alex is the boy who wears glasses.","zh":"Alex 是戴眼镜的男孩。"},{"en":"This is the lab where we study science.","zh":"这是我们学科学的实验室。"}],"questions":[{"prompt":"Phoebe is the friend ___ reads carefully.","options":["where","which","who"],"answer":2,"why":"friend 指人，后面用 who。","kind":"grammar","id":"u0-g1-q0"},{"prompt":"This is the room ___ the accident happened.","options":["where","who","which it"],"answer":0,"why":"这里说明事故发生的地点，用 where。","kind":"grammar","id":"u0-g1-q1"}]}],"song":{"title":"The Time Travellers","page":6,"type":"song","task":["翻到第 6 页，找到歌词中的地点和人物；这里只提供电脑语音，不提供原曲。","从歌词和第 7 页对话各选一个以前的冒险，说明它发生在哪里。","说两句新句子：They have already … / They have not … yet."]},"extra":[],"phonics":{"title":"双元音：/aɪ/ 与 /eɪ/","note":"对应第 6 页 Spelling patterns。比较 nice / exciting 的 /aɪ/ 与 tasty / amazing 的 /eɪ/；字母不同也可能有相同元音。下面为新编朗读词组。","pairs":[{"a":"nice","b":"exciting"},{"a":"tasty","b":"amazing"},{"a":"time","b":"gate"}],"page":6,"questions":[{"prompt":"哪个词与 nice 含有相同的 /aɪ/ 元音？","options":["time","gate","net"],"answer":0,"why":"nice 与 time 含 /aɪ/；gate 是 /eɪ/，net 是 /e/。","kind":"phonics","id":"u0-ph-q0"}]},"story":{"title":"Back in time again","pages":[8,9],"kind":"依据课文的教学改写","summary":"同一天的科学课再次出现。孩子们想阻止旧事故，却因为护目镜碰倒粉末发生了新事故，黄色光门再次打开。","sentences":[{"en":"The children return to their science lesson with Mr Davis.","zh":"孩子们回到 Davis 老师的科学课上。","note":"return to 表示回到；先交代人物与地点。","id":"u0-story-s0"},{"en":"Phoebe notices that the date is the same as before: 11 April.","zh":"Phoebe 注意到日期和上次一样：4 月 11 日。","note":"the same as 是“与……相同”。","id":"u0-story-s1"},{"en":"Alex worries that another accident will happen.","zh":"Alex 担心又会发生事故。","note":"worries that 后面接担心的事情。","id":"u0-story-s2"},{"en":"Last time, Patrick knocked over the water and spoiled the experiment.","zh":"上次 Patrick 碰倒了水，弄坏了实验。","note":"knocked over 是“碰倒”，不是主动倒水。","id":"u0-story-s3"},{"en":"This time, Phoebe tells Patrick to sit still and touch nothing.","zh":"这次 Phoebe 让 Patrick 坐好，什么也别碰。","note":"this time 与 last time 对照。","id":"u0-story-s4"},{"en":"Alex and Phoebe read the instructions and measure the mixture carefully.","zh":"Alex 和 Phoebe 仔细读说明、量好混合物。","note":"carefully 说明他们做事的方式。","id":"u0-story-s5"},{"en":"Mr Davis asks Patrick to put his safety goggles on.","zh":"Davis 老师让 Patrick 戴好护目镜。","note":"ask someone to do 表示让某人做某事。","id":"u0-story-s6"},{"en":"Patrick's goggles fly up and hit a jar of blue powder.","zh":"Patrick 的护目镜飞起来，碰到一罐蓝色粉末。","note":"先找主语 goggles，再找两个动作 fly、hit。","id":"u0-story-s7"},{"en":"The powder falls into the mixture, and an explosion follows.","zh":"粉末掉进混合物，接着发生了爆炸。","note":"and 连接前因与后果；这是虚构情节。","id":"u0-story-s8"},{"en":"The yellow light appears, and the three friends enter it together.","zh":"黄色的光出现了，三个朋友一起走进去。","note":"enter 就是 go into；光门引出新一册冒险。","id":"u0-story-s9"}],"questions":[{"prompt":"这次事故的直接原因是什么？","options":["护目镜碰倒了粉末罐。","孩子们把窗户打开了。","Patrick 又碰倒了水。"],"answer":0,"why":"上次是水；这次是护目镜撞到蓝色粉末罐。注意区分两次事故。","kind":"meaning","id":"u0-story-q0"},{"prompt":"为什么看到 4 月 11 日让 Phoebe 感到奇怪？","options":["那是新学期结束的日子。","它与第一次穿越发生的日期相同。","她忘了带生日礼物。"],"answer":1,"why":"日期重复，让孩子们担心同样的冒险会再发生。","kind":"meaning","id":"u0-story-q1"}]},"reading":{"title":"Remembering the Time Travellers","pages":[7],"kind":"依据课文的教学改写","summary":"两位同学回顾第五册的冒险。读懂“地点、人物和事情”的说明，比一次记住全部故事更重要。","sentences":[{"en":"Two friends discuss the Time Travellers' earlier adventures.","zh":"两个朋友谈论时间旅行者之前的冒险。","note":"earlier adventures 指前面发生过的故事。","id":"u0-reading-s0"},{"en":"One favourite episode takes place in a rainforest.","zh":"一个受喜爱的故事发生在热带雨林。","note":"take place 表示发生；episode 是一集或一个篇章。","id":"u0-reading-s1"},{"en":"The children had to jump from a waterfall in that episode.","zh":"在那一篇里，孩子们不得不从瀑布跳下。","note":"这是对虚构故事的回顾，不是现实活动建议。","id":"u0-reading-s2"},{"en":"Another favourite is the episode in which they meet Elvis.","zh":"另一个受喜爱的故事是他们遇见 Elvis 的那一篇。","note":"in which 指“在那一篇故事中”。","id":"u0-reading-s3"},{"en":"They also remember the mysterious ship called the Mary Celeste.","zh":"他们还记得名叫 Mary Celeste 的神秘船。","note":"called 在这里相当于“名叫”。","id":"u0-reading-s4"},{"en":"The ship did not disappear, but its captain and sailors did.","zh":"消失的不是船，而是船长和水手。","note":"did 代替前面的 disappear，避免重复。","id":"u0-reading-s5"},{"en":"Patrick is described as the boy who wants to do brave things.","zh":"Patrick 被描述为那个总想做勇敢事情的男孩。","note":"who 从句告诉我们是哪个男孩。","id":"u0-reading-s6"},{"en":"Phoebe is the friend who often knows where they are.","zh":"Phoebe 是那个常常知道他们身在何处的朋友。","note":"where they are 是“他们在哪里”。","id":"u0-reading-s7"}],"questions":[{"prompt":"Mary Celeste 对话纠正了哪一个误解？","options":["消失的是船上的人，不是船。","Elvis 是船长。","船停在学校操场。"],"answer":0,"why":"对话强调船没有消失，船长和水手消失了。","kind":"meaning","id":"u0-reading-q0"},{"prompt":"谁常常判断出大家到了哪里？","options":["Mr Davis","Patrick","Phoebe"],"answer":2,"why":"Phoebe 的人物特点是了解地点与背景。","kind":"meaning","id":"u0-reading-q1"}]},"world":{"title":"A careful reader’s experiment","pages":[8,9],"kind":"依据单元目标新编","summary":"新编学习策略：像检查实验步骤一样读长文，先看人物地点，再找事件顺序与因果证据。","sentences":[{"en":"Before a long story, I look at the title and the pictures.","zh":"读长故事之前，我先看标题和图片。","note":"before 在这里引出时间；这是新编的阅读方法。","id":"u0-world-s0"},{"en":"I ask who is there, where they are and what the problem is.","zh":"我问：有谁、在哪里、遇到了什么问题。","note":"三个问题帮助建立故事框架。","id":"u0-world-s1"},{"en":"I read a small part and mark one word that I need to learn.","zh":"我读一小段，标出一个需要学习的词。","note":"a small part 提醒我们分段完成。","id":"u0-world-s2"},{"en":"I use first, next and finally to connect the events.","zh":"我用 first、next、finally 把事件连起来。","note":"这些顺序词帮助复述，而不是逐字背诵。","id":"u0-world-s3"},{"en":"When something happens, I look back for its cause.","zh":"发生一件事时，我回头找它的原因。","note":"cause 是原因；look back 指回看已读部分。","id":"u0-world-s4"},{"en":"I check my answer with a sentence in the story.","zh":"我用故事中的一句话检查答案。","note":"with 表示借助什么来核对。","id":"u0-world-s5"},{"en":"If I am still confused, I read that small part again.","zh":"如果仍然不明白，我就再读那一小段。","note":"again 是再一次，不必每次都从头开始。","id":"u0-world-s6"},{"en":"Then I explain the story in my own words.","zh":"然后我用自己的话讲清故事。","note":"in my own words 是“用自己的话”。","id":"u0-world-s7"}],"questions":[{"prompt":"回答“为什么”时，哪一步最有帮助？","options":["只看图片颜色。","回到相关句子找原因。","跳过所有难词。"],"answer":1,"why":"原因题需要根据文本找到事件之间的联系。","kind":"meaning","id":"u0-world-q0"},{"prompt":"文中的 first、next、finally 帮助我们做什么？","options":["描述事件顺序。","计算单词个数。","猜测所有答案。"],"answer":0,"why":"它们分别表示首先、接着、最后，帮助按顺序讲故事。","kind":"meaning","id":"u0-world-q1"}]},"create":{"title":"一分钟讲清实验事故","pages":[8,9],"tasks":["列出“上次事故”和“这次事故”各自的原因。","用 First / Next / Finally 准备 4–6 句英文复述。","讲给家人听，请对方回答：这次是谁的什么物品碰到了什么？"],"frame":"First, the children …\nThey were worried because …\nThis time, Patrick’s …\nAs a result, …\nFinally, …","model":"The children were back in science class. Phoebe recognised the date. Alex and Phoebe tried to avoid another accident. However, Patrick’s goggles hit a jar of powder. The powder fell into the mixture, and there was an explosion. Finally, the yellow light appeared again.","success":"能说清人物、两次事故的区别、这次的原因与结果；遇到难句可以看关键词再说。","teacher":"依据第 8–9 页故事新编的复述任务；无第六册教师用书核对。"},"questions":[{"prompt":"I have ___ read the instructions.","options":["already","yet","tomorrow"],"answer":0,"why":"肯定句表示“已经读过”，用 already。","kind":"grammar","id":"u0-g0-q0"},{"prompt":"Has Patrick put on his goggles ___?","options":["already yesterday","yet","ago"],"answer":1,"why":"问“已经戴好了吗”，yet 放在疑问句末尾。","kind":"grammar","id":"u0-g0-q1"},{"prompt":"Phoebe is the friend ___ reads carefully.","options":["where","which","who"],"answer":2,"why":"friend 指人，后面用 who。","kind":"grammar","id":"u0-g1-q0"},{"prompt":"This is the room ___ the accident happened.","options":["where","who","which it"],"answer":0,"why":"这里说明事故发生的地点，用 where。","kind":"grammar","id":"u0-g1-q1"},{"prompt":"这次事故的直接原因是什么？","options":["护目镜碰倒了粉末罐。","孩子们把窗户打开了。","Patrick 又碰倒了水。"],"answer":0,"why":"上次是水；这次是护目镜撞到蓝色粉末罐。注意区分两次事故。","kind":"meaning","id":"u0-story-q0"},{"prompt":"为什么看到 4 月 11 日让 Phoebe 感到奇怪？","options":["那是新学期结束的日子。","它与第一次穿越发生的日期相同。","她忘了带生日礼物。"],"answer":1,"why":"日期重复，让孩子们担心同样的冒险会再发生。","kind":"meaning","id":"u0-story-q1"},{"prompt":"Mary Celeste 对话纠正了哪一个误解？","options":["消失的是船上的人，不是船。","Elvis 是船长。","船停在学校操场。"],"answer":0,"why":"对话强调船没有消失，船长和水手消失了。","kind":"meaning","id":"u0-reading-q0"},{"prompt":"谁常常判断出大家到了哪里？","options":["Mr Davis","Patrick","Phoebe"],"answer":2,"why":"Phoebe 的人物特点是了解地点与背景。","kind":"meaning","id":"u0-reading-q1"},{"prompt":"回答“为什么”时，哪一步最有帮助？","options":["只看图片颜色。","回到相关句子找原因。","跳过所有难词。"],"answer":1,"why":"原因题需要根据文本找到事件之间的联系。","kind":"meaning","id":"u0-world-q0"},{"prompt":"文中的 first、next、finally 帮助我们做什么？","options":["描述事件顺序。","计算单词个数。","猜测所有答案。"],"answer":0,"why":"它们分别表示首先、接着、最后，帮助按顺序讲故事。","kind":"meaning","id":"u0-world-q1"},{"prompt":"哪个词与 nice 含有相同的 /aɪ/ 元音？","options":["time","gate","net"],"answer":0,"why":"nice 与 time 含 /aɪ/；gate 是 /eɪ/，net 是 /e/。","kind":"phonics","id":"u0-ph-q0"}]},{"id":1,"title":"The treasure","zh":"海盗的宝藏","start":10,"end":21,"icon":"🏴‍☠️","goal":"讲清宝藏属于谁，并用 for / since 介绍珍爱的物品。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":119,"vocab":[{"word":"palm tree","zh":"棕榈树","example":"The treasure is near a palm tree."},{"word":"spade","zh":"铲子","example":"The gardener uses a spade."},{"word":"hook","zh":"钩子","example":"A coat hangs on the hook."},{"word":"hammock","zh":"吊床","example":"There is a hammock between the trees."},{"word":"eye-patch","zh":"眼罩","example":"The pirate wears an eye-patch in the picture."},{"word":"treasure chest","zh":"宝箱","example":"The treasure chest has a heavy lid."},{"word":"coins","zh":"硬币","example":"There are old coins in the box."},{"word":"key","zh":"钥匙","example":"This key opens the little chest."},{"word":"hole","zh":"洞；坑","example":"The children noticed a hole in the sand."},{"word":"binoculars","zh":"双筒望远镜","example":"We use binoculars to watch birds."}],"grammar":[{"title":"for / since：持续了多久","rule":"现在完成时中，for + 一段时间，since + 开始的时间点。for three years；since 2022。","examples":[{"en":"I have had this book for two years.","zh":"这本书我已经拥有两年了。"},{"en":"She has known him since primary school.","zh":"她从小学起就认识他。"}],"questions":[{"prompt":"I have lived here ___ six months.","options":["since","for","at"],"answer":1,"why":"six months 是时长，用 for。","kind":"grammar","id":"u1-g0-q0"},{"prompt":"He has liked ships ___ he was seven.","options":["for","during","since"],"answer":2,"why":"he was seven 给出起点，用 since。","kind":"grammar","id":"u1-g0-q1"}]},{"title":"How long … ?：询问持续时间","rule":"How long have / has + 主语 + 过去分词 … ? 用 for 或 since 回答。","examples":[{"en":"How long have you had your binoculars?","zh":"你有这副望远镜多久了？"},{"en":"I have had them since my birthday.","zh":"从生日那天起我就有了。"}],"questions":[{"prompt":"___ have you known your friend? — For five years.","options":["How long","How many","How far"],"answer":0,"why":"回答是时长，因此问 How long。","kind":"grammar","id":"u1-g1-q0"},{"prompt":"How long ___ she had this key?","options":["have","has","is"],"answer":1,"why":"主语 she，用 has + 过去分词 had。","kind":"grammar","id":"u1-g1-q1"}]}],"song":{"title":"Get on board!","page":12,"type":"song","task":["在第 12 页找出海盗旅行和寻宝的词；读懂情节，不把海盗行为当作榜样。","找出一句 have + 过去分词，说明它表达的经历。","用英语说一种真正珍爱的“treasure”，可以是一张画或一本书。"]},"extra":[],"phonics":{"title":"-sure 与 -ture","note":"对应第 12 页。treasure、pleasure 中常听到 /ʒə/；nature、adventure 的结尾常有 /tʃə/。听电脑语音后慢读，注意 /tʃ/ 前有短暂阻塞。","pairs":[{"a":"treasure","b":"pleasure"},{"a":"nature","b":"adventure"},{"a":"measure","b":"picture"}],"page":12,"questions":[{"prompt":"哪个词的结尾和 treasure 的 -sure 更接近？","options":["picture","nature","pleasure"],"answer":2,"why":"treasure 与 pleasure 的结尾都是 /ʒə/ 一类声音。","kind":"phonics","id":"u1-ph-q0"}]},"story":{"title":"The pirates’ treasure","pages":[14,15],"kind":"依据课文的教学改写","summary":"朋友们找到海盗埋的金币，却发现它们属于被抢的家庭。他们归还宝藏，又遇到另一伙海盗，最后从光门逃离。","sentences":[{"en":"From a hill, the friends watch the pirate ship sail away.","zh":"朋友们从山坡上看着海盗船驶离。","note":"from a hill 先交代观察位置。","id":"u1-story-s0"},{"en":"They also notice another ship with red sails and a black flag.","zh":"他们还注意到另一艘有红帆和黑旗的船。","note":"another 是另一个；这是一条后面有用的线索。","id":"u1-story-s1"},{"en":"The children dig up a treasure chest filled with gold coins.","zh":"孩子们挖出一个装满金币的宝箱。","note":"filled with 是装满；dig up 表示挖出来。","id":"u1-story-s2"},{"en":"Patrick thinks the treasure is theirs, but Phoebe disagrees.","zh":"Patrick 觉得宝藏归他们了，Phoebe 却不同意。","note":"theirs 表示他们的；but 提示意见不同。","id":"u1-story-s3"},{"en":"Soon, tired families arrive on a boat.","zh":"不久，一些疲惫的家庭乘船来到这里。","note":"soon 推动时间向前。","id":"u1-story-s4"},{"en":"A woman explains that pirates stole the money for their new farms.","zh":"一个女人解释说，海盗抢走了他们买新农场的钱。","note":"the money for … 表示准备用于……的钱。","id":"u1-story-s5"},{"en":"The friends return the chest and send the families towards a town.","zh":"朋友们归还宝箱，并告诉这些家庭往一个城镇走。","note":"return 在这里是归还，不是回来。","id":"u1-story-s6"},{"en":"At midnight, more pirates arrive with the first captain as their prisoner.","zh":"午夜，更多海盗押着先前的船长来了。","note":"as their prisoner 说明船长现在的处境。","id":"u1-story-s7"},{"en":"Alex sneezes, and the hidden children are discovered.","zh":"Alex 打了个喷嚏，藏着的孩子们被发现了。","note":"are discovered 是被发现。","id":"u1-story-s8"},{"en":"The pirates demand the treasure, but a yellow glow appears in the hole.","zh":"海盗索要宝藏，但坑里出现了黄色的光。","note":"demand 比 ask 更强硬，表示强令交出。","id":"u1-story-s9"},{"en":"The three friends jump into the light and escape.","zh":"三个朋友跳进光里，逃走了。","note":"先归还宝藏，再逃离危险，复述时不要换序。","id":"u1-story-s10"}],"questions":[{"prompt":"为什么 Phoebe 认为他们不能留下金币？","options":["金币太重。","金币属于被海盗抢劫的家庭。","宝箱没有钥匙。"],"answer":1,"why":"找到不等于拥有；后来女人的解释确认了金币的主人。","kind":"meaning","id":"u1-story-q0"},{"prompt":"哪件事让藏起来的孩子暴露了？","options":["Alex 打喷嚏。","Patrick 敲学校的铃。","Phoebe 点亮太阳能板。"],"answer":0,"why":"午夜躲藏时 Alex 打喷嚏，引来了海盗。","kind":"meaning","id":"u1-story-q1"}]},"reading":{"title":"A Roman helmet found","pages":[16],"kind":"依据课文的教学改写","summary":"一位使用金属探测器的人发现头盔碎片。专家拼合后判断其用途；读者要区分文章提供的证据和没有说的事情。","sentences":[{"en":"The textbook article describes the discovery of an old Roman helmet.","zh":"教材文章讲述了一顶古罗马头盔的发现。","note":"这是旧版文章的阅读改写，不含今日价格或法律建议。","id":"u1-reading-s0"},{"en":"A man with a metal detector found pieces of it in an English village.","zh":"一个带着金属探测器的人在英国一个村庄发现了它的碎片。","note":"pieces of it 指头盔的碎片。","id":"u1-reading-s1"},{"en":"At first, he did not know what the pieces were.","zh":"起初，他不知道这些碎片是什么。","note":"at first 和后面的发现形成对照。","id":"u1-reading-s2"},{"en":"He showed them to experts, who put the pieces together.","zh":"他把它们拿给专家看，专家把碎片拼在一起。","note":"them 回指 pieces；who 指 experts。","id":"u1-reading-s3"},{"en":"The helmet is made of copper and includes a face mask.","zh":"头盔由铜制成，还包括一个面罩。","note":"is made of 表示材料。","id":"u1-reading-s4"},{"en":"Its decoration includes a creature with parts of a lion and an eagle.","zh":"装饰中有一种兼具狮子和鹰特征的生物。","note":"creature 是生物；这里指神话形象。","id":"u1-reading-s5"},{"en":"The experts in the article think it was worn in military parades.","zh":"文中的专家认为它是军队游行时佩戴的。","note":"think 表示根据证据作出的判断。","id":"u1-reading-s6"},{"en":"They do not think it was an ordinary helmet for fighting.","zh":"他们认为它不是作战时用的普通头盔。","note":"ordinary 是普通的；注意用途的对比。","id":"u1-reading-s7"},{"en":"The report shows how experts can help explain an unusual discovery.","zh":"这篇报道说明专家能怎样帮助解释不寻常的发现。","note":"discovery 是发现；主题是观察和求证。","id":"u1-reading-s8"}],"questions":[{"prompt":"发现者一开始知道这些碎片是什么吗？","options":["知道，他自己制作了它。","不知道，后来请教了专家。","文章说他是一位罗马士兵。"],"answer":1,"why":"文中说他起初不知道，后来把碎片给专家看。","kind":"meaning","id":"u1-reading-q0"},{"prompt":"按照文中专家的判断，这顶头盔可能用于什么？","options":["军队游行。","学校篮球比赛。","游泳时保护头部。"],"answer":0,"why":"文章将游行时佩戴与战斗时佩戴作了区分。","kind":"meaning","id":"u1-reading-q1"}]},"world":{"title":"Treasure Island and types of writing","pages":[18,19],"kind":"依据课文的教学改写","summary":"认识《金银岛》的开头和第一人称叙述，再分清简介、评论与传记分别告诉读者什么。","sentences":[{"en":"Treasure Island is an adventure story by Robert Louis Stevenson.","zh":"《金银岛》是 Robert Louis Stevenson 写的冒险故事。","note":"by 后接作者。","id":"u1-world-s0"},{"en":"The opening is told by a character who uses I and my.","zh":"开头由一个使用 I 和 my 的人物来讲述。","note":"这叫第一人称叙述。","id":"u1-world-s1"},{"en":"He remembers a strange sailor arriving at his father's inn.","zh":"他回忆一个奇怪的水手来到父亲的客栈。","note":"inn 是提供住宿与饭食的客栈。","id":"u1-world-s2"},{"en":"The sailor has a sea chest, a scar and a rough appearance.","zh":"水手带着航海箱，脸上有伤疤，外表粗犷。","note":"这些细节帮助读者想象人物。","id":"u1-world-s3"},{"en":"He asks people to call him captain and pays to stay.","zh":"他让大家称他船长，并付钱住下来。","note":"ask people to … 表示让别人怎样做。","id":"u1-world-s4"},{"en":"A blurb introduces a book and tries to make people want to read it.","zh":"内容简介介绍一本书，吸引人们去读。","note":"blurb 通常是封面或封底的短介绍。","id":"u1-world-s5"},{"en":"A review gives an opinion about what works well or less well.","zh":"评论说出哪些地方好、哪些地方不够好。","note":"opinion 是观点，需要理由支持。","id":"u1-world-s6"},{"en":"A biography tells the story of a real person's life.","zh":"传记讲述一个真实人物的一生。","note":"biography 关注人物生平，不是小说情节。","id":"u1-world-s7"}],"questions":[{"prompt":"看到 I、my 等词，可判断这段故事采用什么叙述方式？","options":["第一人称。","天气预报。","商品价格表。"],"answer":0,"why":"讲述者以自己的身份说 I 和 my。","kind":"meaning","id":"u1-world-q0"},{"prompt":"如果想说明自己喜欢一本书的哪些地方，应写什么？","options":["biography","review","shopping list"],"answer":1,"why":"review 是评论，可以表达喜好与理由。","kind":"meaning","id":"u1-world-q1"}]},"create":{"title":"我的珍宝：Show and tell","pages":[20,21],"tasks":["选一个真实或画出来的珍爱物品，说明它为什么特别。","写出你怎样得到它、拥有多久，以及一个相关回忆。","用约一分钟展示它，结尾邀请听众提问；不需要展示贵重物品。"],"frame":"This is my treasure.\nI got it from …\nI have had it for / since …\nIt matters to me because …\nThank you for listening. Do you have any questions?","model":"This drawing is my treasure. My brother made it for me. I have had it since my last birthday. It shows our family in the garden. It is important because it reminds me of a happy day. Thank you for listening.","success":"说明物品、来源、持续时间与个人意义；for / since 使用恰当，并能回答一个问题。","teacher":"对应第 20 页展示活动与第 21 页个人记录；示范文字新编。"},"questions":[{"prompt":"I have lived here ___ six months.","options":["since","for","at"],"answer":1,"why":"six months 是时长，用 for。","kind":"grammar","id":"u1-g0-q0"},{"prompt":"He has liked ships ___ he was seven.","options":["for","during","since"],"answer":2,"why":"he was seven 给出起点，用 since。","kind":"grammar","id":"u1-g0-q1"},{"prompt":"___ have you known your friend? — For five years.","options":["How long","How many","How far"],"answer":0,"why":"回答是时长，因此问 How long。","kind":"grammar","id":"u1-g1-q0"},{"prompt":"How long ___ she had this key?","options":["have","has","is"],"answer":1,"why":"主语 she，用 has + 过去分词 had。","kind":"grammar","id":"u1-g1-q1"},{"prompt":"为什么 Phoebe 认为他们不能留下金币？","options":["金币太重。","金币属于被海盗抢劫的家庭。","宝箱没有钥匙。"],"answer":1,"why":"找到不等于拥有；后来女人的解释确认了金币的主人。","kind":"meaning","id":"u1-story-q0"},{"prompt":"哪件事让藏起来的孩子暴露了？","options":["Alex 打喷嚏。","Patrick 敲学校的铃。","Phoebe 点亮太阳能板。"],"answer":0,"why":"午夜躲藏时 Alex 打喷嚏，引来了海盗。","kind":"meaning","id":"u1-story-q1"},{"prompt":"发现者一开始知道这些碎片是什么吗？","options":["知道，他自己制作了它。","不知道，后来请教了专家。","文章说他是一位罗马士兵。"],"answer":1,"why":"文中说他起初不知道，后来把碎片给专家看。","kind":"meaning","id":"u1-reading-q0"},{"prompt":"按照文中专家的判断，这顶头盔可能用于什么？","options":["军队游行。","学校篮球比赛。","游泳时保护头部。"],"answer":0,"why":"文章将游行时佩戴与战斗时佩戴作了区分。","kind":"meaning","id":"u1-reading-q1"},{"prompt":"看到 I、my 等词，可判断这段故事采用什么叙述方式？","options":["第一人称。","天气预报。","商品价格表。"],"answer":0,"why":"讲述者以自己的身份说 I 和 my。","kind":"meaning","id":"u1-world-q0"},{"prompt":"如果想说明自己喜欢一本书的哪些地方，应写什么？","options":["biography","review","shopping list"],"answer":1,"why":"review 是评论，可以表达喜好与理由。","kind":"meaning","id":"u1-world-q1"},{"prompt":"哪个词的结尾和 treasure 的 -sure 更接近？","options":["picture","nature","pleasure"],"answer":2,"why":"treasure 与 pleasure 的结尾都是 /ʒə/ 一类声音。","kind":"phonics","id":"u1-ph-q0"}]},{"id":2,"title":"Future transport","zh":"未来交通","start":22,"end":33,"icon":"🚝","goal":"分清必须做的准备与未来预测，用证据解释 Patrick 的困难。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":120,"vocab":[{"word":"monorail","zh":"单轨列车","example":"The monorail runs above the road."},{"word":"cable car","zh":"缆车","example":"The cable car goes up the mountain."},{"word":"parachute","zh":"降落伞","example":"The story shows a colourful parachute."},{"word":"solar panel","zh":"太阳能板","example":"There is a solar panel on the roof."},{"word":"microlight","zh":"超轻型飞机","example":"We saw a microlight in a photograph."},{"word":"hang-glider","zh":"悬挂式滑翔机","example":"The hang-glider has wide wings."},{"word":"jet pack","zh":"喷气背包","example":"The imaginary jet pack can fly."},{"word":"wind turbine","zh":"风力发电机","example":"The wind turbine turns in the wind."},{"word":"surfboard","zh":"冲浪板","example":"The blue surfboard is beside the sea."},{"word":"floating skateboard","zh":"悬浮滑板","example":"The future city has floating skateboards."}],"grammar":[{"title":"need to / do not need to","rule":"need to + 动词原形表示需要做；do not need to 表示没有必要做，不是“禁止做”。主语 he / she 用 needs / does not need。","examples":[{"en":"You need to read the instructions.","zh":"你需要读说明书。"},{"en":"We do not need to hurry today.","zh":"我们今天不用着急。"}],"questions":[{"prompt":"You need ___ the safety instructions.","options":["reading","to read","readed"],"answer":1,"why":"need to 后接动词原形 read。","kind":"grammar","id":"u2-g0-q0"},{"prompt":"You do not need to bring a pen. 意思是？","options":["你不必带笔。","你绝对不能带笔。","你已经丢了笔。"],"answer":0,"why":"do not need to 表示没有必要，不等于 must not。","kind":"grammar","id":"u2-g0-q1"}]},{"title":"will / will not：预测未来","rule":"will + 动词原形；will not 可缩写为 won’t。预测是看法，不是已经证实的事实。","examples":[{"en":"I think more people will use trains.","zh":"我认为会有更多人使用列车。"},{"en":"Perhaps future cars will not need petrol.","zh":"也许未来汽车不需要汽油。"}],"questions":[{"prompt":"In my future city, buses ___ be quieter.","options":["were","having","will"],"answer":2,"why":"在预测未来，使用 will + 动词原形。","kind":"grammar","id":"u2-g1-q0"},{"prompt":"Which sentence is a prediction?","options":["I think travel will be easier.","I travelled yesterday.","I am on a bus now."],"answer":0,"why":"will be 表示对未来的预测；另外两句是过去或现在。","kind":"grammar","id":"u2-g1-q1"}]}],"song":{"title":"Expressing interest：表现出兴趣","page":24,"type":"dialogue","task":["阅读第 24 页 Mia 和 Josh 的对话，找出 Really? / Tell me more. / Wow!。","说清 Josh 为什么担心 Mia，再选一个安全的爱好做双人对话。","听对方说完，回应一句表示兴趣的话，再问一个相关问题。"]},"extra":[],"phonics":{"title":"对话语气：表示兴趣","note":"这是依据第 24 页功能对话新编的发音练习，不是本单元原版 phonics 专页。把 Really? 和 Tell me more. 当作完整意群，留意语气。","pairs":[{"a":"Really?","b":"Tell me more."},{"a":"I see.","b":"That sounds interesting."},{"a":"Wow!","b":"What happened next?"}],"page":24,"questions":[{"prompt":"哪一句最能鼓励别人继续介绍爱好？","options":["Tell me more.","Put it in the bin.","It is a red key."],"answer":0,"why":"Tell me more. 表示“多告诉我一些”，用于表达兴趣。","kind":"phonics","id":"u2-ph-q0"}]},"story":{"title":"A problem for Patrick","pages":[26,27],"kind":"依据课文的教学改写","summary":"Alex 和 Phoebe 先读说明再飞行；Patrick 没认真听，失去控制。朋友们告诉他如何打开故事里的应急降落伞，帮助他安全降落。","sentences":[{"en":"Alex and Phoebe read the jet-pack instructions before they take off.","zh":"Alex 和 Phoebe 起飞前读了喷气背包说明。","note":"before 明确动作先后；喷气背包是此处的科幻装置。","id":"u2-story-s0"},{"en":"They feel nervous, but they understand how the controls work.","zh":"他们有些紧张，不过理解了控制装置的作用。","note":"but 表示紧张不等于没有准备。","id":"u2-story-s1"},{"en":"They fly towards a mountain and see a cable car below.","zh":"他们飞向一座山，看见下面有一辆缆车。","note":"towards 表示朝着，不一定已经到达。","id":"u2-story-s2"},{"en":"After exploring the area, Phoebe starts to worry about Patrick.","zh":"在附近飞行之后，Phoebe 开始担心 Patrick。","note":"worry about 后面接担心的人或事。","id":"u2-story-s3"},{"en":"He was too impatient to listen to the lesson.","zh":"他太心急，没有听完讲解。","note":"too … to … 表示太……而不能……。","id":"u2-story-s4"},{"en":"Suddenly, they see Patrick falling quickly through the sky.","zh":"突然，他们看见 Patrick 在空中快速下落。","note":"see someone doing 强调看见正在发生的动作。","id":"u2-story-s5"},{"en":"His friends realise that he cannot control his jet pack.","zh":"朋友们意识到他无法控制喷气背包。","note":"realise 是意识到；这是问题的核心。","id":"u2-story-s6"},{"en":"They fly closer and tell him to use the emergency controls.","zh":"他们飞近，告诉他使用应急控制装置。","note":"故事中的按钮不是现实设备说明。","id":"u2-story-s7"},{"en":"A parachute opens, and Patrick reaches the ground safely.","zh":"降落伞打开了，Patrick 安全落地。","note":"safely 是安全地。","id":"u2-story-s8"},{"en":"He thanks his friends, and they leave through the yellow light.","zh":"他感谢朋友，大家穿过黄光离开了。","note":"结尾的感谢说明他意识到朋友帮助的重要。","id":"u2-story-s9"}],"questions":[{"prompt":"Patrick 为什么遇到困难？","options":["他没有认真听使用说明。","他先读完了全部说明。","他的朋友把缆车拆了。"],"answer":0,"why":"故事直接说他太心急，没有听讲，所以不知道怎样控制背包。","kind":"meaning","id":"u2-story-q0"},{"prompt":"哪个顺序符合故事？","options":["感谢朋友 → 失控 → 朋友靠近。","失控 → 朋友靠近帮助 → 降落伞打开。","降落伞打开 → 到学校 → 开始读说明。"],"answer":1,"why":"抓住危险、帮助与解决三个环节。","kind":"meaning","id":"u2-story-q1"}]},"reading":{"title":"Getting around Bangkok","pages":[28],"kind":"依据课文的教学改写","summary":"文章比较嘟嘟车与高架列车怎样帮助人们穿行城市。学习交通方式的特点，不把旧版费用与客流描述当作今天的出行信息。","sentences":[{"en":"The textbook compares two ways of travelling around Bangkok.","zh":"教材比较了在曼谷出行的两种方式。","note":"compare 是比较；这里只练阅读理解。","id":"u2-reading-s0"},{"en":"Busy roads can make a journey through the city slow.","zh":"繁忙的道路可能让穿越城市的旅程很慢。","note":"can 表示可能，并非每一次都如此。","id":"u2-reading-s1"},{"en":"A tuk-tuk is easy to recognise because it has three wheels.","zh":"嘟嘟车容易辨认，因为它有三个轮子。","note":"because 解释容易辨认的原因。","id":"u2-reading-s2"},{"en":"The driver sits at the front, and passengers sit behind.","zh":"司机坐在前面，乘客坐在后面。","note":"front 和 behind 是位置对比。","id":"u2-reading-s3"},{"en":"The article says a tuk-tuk ride can feel fast and exciting.","zh":"文章说，乘坐嘟嘟车可能让人觉得快而刺激。","note":"can feel 描述体验，不是推荐冒险。","id":"u2-reading-s4"},{"en":"The skytrain offers a different way to cross the city.","zh":"高架列车提供另一种穿行城市的方法。","note":"offers 是提供；different 引出对比。","id":"u2-reading-s5"},{"en":"Its trains run on tracks above the street traffic.","zh":"它的列车在街道交通上方的轨道行驶。","note":"above 表示在上方。","id":"u2-reading-s6"},{"en":"They use electricity, but the route does not reach every possible destination.","zh":"列车用电，不过线路并不能到达每一个目的地。","note":"but 提示一种交通方式也有局限。","id":"u2-reading-s7"},{"en":"A good comparison explains both useful features and limitations.","zh":"好的比较会同时说明有用的特点和局限。","note":"both … and … 表示两方面都考虑。","id":"u2-reading-s8"}],"questions":[{"prompt":"嘟嘟车在文中最容易辨认的外形特征是什么？","options":["只有一个轮子。","有三个轮子。","有飞机机翼。"],"answer":1,"why":"文中 because 后明确说明三个轮子这一特征。","kind":"meaning","id":"u2-reading-q0"},{"prompt":"高架列车怎样避开街道上的车流？","options":["在车流上方的轨道行驶。","每位乘客背上喷气背包。","它在水下航行。"],"answer":0,"why":"above the street traffic 是理解这一优势的关键词。","kind":"meaning","id":"u2-reading-q1"}]},"world":{"title":"The history of the car","pages":[30,31],"kind":"依据课文的教学改写","summary":"按时间线理解车辆的发展：动力、速度、制造方式和污染问题不断变化。“未来的车”是想象，不等于已发生的历史。","sentences":[{"en":"The textbook uses a timeline to explain changes in cars.","zh":"教材用时间线解释汽车的变化。","note":"timeline 把历史事件按时间排列。","id":"u2-world-s0"},{"en":"Early steam-powered vehicles moved slowly and had special jobs.","zh":"早期蒸汽动力车辆行驶缓慢，并有特定用途。","note":"steam-powered 表示由蒸汽提供动力。","id":"u2-world-s1"},{"en":"Cugnot's heavy cart was designed to pull military equipment.","zh":"Cugnot 的重型车被设计来拖运军事装备。","note":"was designed to 说明设计用途。","id":"u2-world-s2"},{"en":"Later, engineers developed vehicles that could carry people without horses.","zh":"后来，工程师改进了不用马就能载人的车辆。","note":"without horses 强调与马车的差异。","id":"u2-world-s3"},{"en":"As engines improved, vehicles became faster.","zh":"随着发动机改进，车辆变得更快。","note":"as 在此表示随着。","id":"u2-world-s4"},{"en":"Road safety became a problem that people had to think about.","zh":"道路安全成了人们必须考虑的问题。","note":"that 后面说明是什么样的问题。","id":"u2-world-s5"},{"en":"Factories found ways to produce cars in larger numbers.","zh":"工厂找到批量生产汽车的方法。","note":"in larger numbers 表示更大量地。","id":"u2-world-s6"},{"en":"The timeline also introduces concerns about pollution from traffic.","zh":"时间线还介绍了人们对交通污染的担忧。","note":"concerns about 是对……的担忧。","id":"u2-world-s7"},{"en":"A future invention belongs in a prediction, not among events that already happened.","zh":"未来的发明应放在预测中，而不是当作已经发生的事件。","note":"already happened 与 future prediction 要分开。","id":"u2-world-s8"}],"questions":[{"prompt":"时间线通常怎样组织内容？","options":["按事件发生的先后。","按词语字母顺序。","只按图片大小。"],"answer":0,"why":"timeline 的主要结构是时间先后。","kind":"meaning","id":"u2-world-q0"},{"prompt":"哪一项应标为预测而不是历史事件？","options":["早期车辆使用蒸汽。","未来每家也许都有飞行汽车。","工厂曾改进制造方法。"],"answer":1,"why":"“未来”“也许”表示尚未发生、不能当作事实的预测。","kind":"meaning","id":"u2-world-q1"}]},"create":{"title":"设计一座未来交通城市","pages":[32,33],"tasks":["画出 3 种交通方式，并给每种写一条用途或限制。","写 4 句预测，至少包含一句 will not。","与伙伴做城市导览对话，问一句 Do we need to … ? 并给出理由。"],"frame":"In my future city, people will …\nThey will not …\nTo use this transport, you need to …\nYou do not need to …\nI think this will help because …","model":"In my future city, people will use quiet electric trains. The trains will run above busy roads. We will not need a car for every short journey. People will need to follow the safety rules. I think travelling will be easier, but this is only my prediction.","success":"区分预测与事实；至少说出一种优势、一种限制和一项必要准备。","teacher":"对应第 32 页角色对话与第 33 页未来生活问卷；转换为新编城市设计表达任务。"},"questions":[{"prompt":"You need ___ the safety instructions.","options":["reading","to read","readed"],"answer":1,"why":"need to 后接动词原形 read。","kind":"grammar","id":"u2-g0-q0"},{"prompt":"You do not need to bring a pen. 意思是？","options":["你不必带笔。","你绝对不能带笔。","你已经丢了笔。"],"answer":0,"why":"do not need to 表示没有必要，不等于 must not。","kind":"grammar","id":"u2-g0-q1"},{"prompt":"In my future city, buses ___ be quieter.","options":["were","having","will"],"answer":2,"why":"在预测未来，使用 will + 动词原形。","kind":"grammar","id":"u2-g1-q0"},{"prompt":"Which sentence is a prediction?","options":["I think travel will be easier.","I travelled yesterday.","I am on a bus now."],"answer":0,"why":"will be 表示对未来的预测；另外两句是过去或现在。","kind":"grammar","id":"u2-g1-q1"},{"prompt":"Patrick 为什么遇到困难？","options":["他没有认真听使用说明。","他先读完了全部说明。","他的朋友把缆车拆了。"],"answer":0,"why":"故事直接说他太心急，没有听讲，所以不知道怎样控制背包。","kind":"meaning","id":"u2-story-q0"},{"prompt":"哪个顺序符合故事？","options":["感谢朋友 → 失控 → 朋友靠近。","失控 → 朋友靠近帮助 → 降落伞打开。","降落伞打开 → 到学校 → 开始读说明。"],"answer":1,"why":"抓住危险、帮助与解决三个环节。","kind":"meaning","id":"u2-story-q1"},{"prompt":"嘟嘟车在文中最容易辨认的外形特征是什么？","options":["只有一个轮子。","有三个轮子。","有飞机机翼。"],"answer":1,"why":"文中 because 后明确说明三个轮子这一特征。","kind":"meaning","id":"u2-reading-q0"},{"prompt":"高架列车怎样避开街道上的车流？","options":["在车流上方的轨道行驶。","每位乘客背上喷气背包。","它在水下航行。"],"answer":0,"why":"above the street traffic 是理解这一优势的关键词。","kind":"meaning","id":"u2-reading-q1"},{"prompt":"时间线通常怎样组织内容？","options":["按事件发生的先后。","按词语字母顺序。","只按图片大小。"],"answer":0,"why":"timeline 的主要结构是时间先后。","kind":"meaning","id":"u2-world-q0"},{"prompt":"哪一项应标为预测而不是历史事件？","options":["早期车辆使用蒸汽。","未来每家也许都有飞行汽车。","工厂曾改进制造方法。"],"answer":1,"why":"“未来”“也许”表示尚未发生、不能当作事实的预测。","kind":"meaning","id":"u2-world-q1"},{"prompt":"哪一句最能鼓励别人继续介绍爱好？","options":["Tell me more.","Put it in the bin.","It is a red key."],"answer":0,"why":"Tell me more. 表示“多告诉我一些”，用于表达兴趣。","kind":"phonics","id":"u2-ph-q0"}]},{"id":3,"title":"Ancient Egypt","zh":"古埃及","start":34,"end":45,"icon":"🔺","goal":"按顺序解释故事和形状，用被动语态说明物品怎样被制作。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":121,"vocab":[{"word":"pyramid","zh":"金字塔；棱锥","example":"We made a paper pyramid."},{"word":"Sphinx","zh":"狮身人面像","example":"The Sphinx appears in our history picture."},{"word":"pharaoh","zh":"法老","example":"A pharaoh was a ruler of Ancient Egypt."},{"word":"chariot","zh":"古代双轮马车","example":"The museum has a model chariot."},{"word":"slaves","zh":"奴隶；被奴役的人","example":"The text uses the word slaves for people who were not free."},{"word":"rock","zh":"岩石","example":"The model stands on a flat rock."},{"word":"hieroglyphics","zh":"象形文字","example":"The wall has pictures of hieroglyphics."},{"word":"tomb","zh":"陵墓","example":"The guide showed us a photograph of a tomb."},{"word":"mummy","zh":"木乃伊","example":"There is a mummy in the adventure story."}],"grammar":[{"title":"过去时被动语态","rule":"was / were + 过去分词，强调某物“被怎样处理”。单数用 was，复数用 were。例句练语言，不把旧教材的古代施工推测当成已证实史实。","examples":[{"en":"The model was made from paper.","zh":"模型是用纸做的。"},{"en":"The pictures were painted yesterday.","zh":"这些画是昨天画的。"}],"questions":[{"prompt":"The paper pyramid ___ made yesterday.","options":["were","was","has"],"answer":1,"why":"pyramid 是单数，过去时被动语态用 was made。","kind":"grammar","id":"u3-g0-q0"},{"prompt":"The stones were ___ to the museum.","options":["take","taking","taken"],"answer":2,"why":"被动语态用过去分词，take 的过去分词是 taken。","kind":"grammar","id":"u3-g0-q1"}]},{"title":"a lot of / a few / a little","rule":"a lot of / lots of 可接可数复数或不可数名词；a few + 可数复数，a little + 不可数名词。","examples":[{"en":"There are a few symbols on the wall.","zh":"墙上有几个符号。"},{"en":"We need a little water and a lot of paper.","zh":"我们需要一点水和很多纸。"}],"questions":[{"prompt":"We have ___ small stones.","options":["a few","a little","much a"],"answer":0,"why":"stones 可数且为复数，表示几个用 a few。","kind":"grammar","id":"u3-g1-q0"},{"prompt":"There is ___ water in the cup.","options":["a few","a little","many"],"answer":1,"why":"water 是不可数名词，表示一点用 a little。","kind":"grammar","id":"u3-g1-q1"}]}],"song":{"title":"In old Cairo","page":36,"type":"song","task":["在第 36 页标出故事发生的地点和出现的人物。","用三句英语说出“发现木乃伊 → 逃跑 → 木乃伊回到墓中”的歌曲情节。","找出过去式动词，按 /t/、/d/、/ɪd/ 分类读一读；原曲需自备音频。"]},"extra":[],"phonics":{"title":"-ed 的三种读法","note":"对应第 36 页。清辅音（/t/ 除外）后常读 /t/；浊辅音（/d/ 除外）和元音后常读 /d/；/t/、/d/ 后读 /ɪd/，增加一个音节。","pairs":[{"a":"looked","b":"watched"},{"a":"played","b":"opened"},{"a":"wanted","b":"shouted"}],"page":36,"questions":[{"prompt":"哪一个词的 -ed 读 /ɪd/，增加一个音节？","options":["looked","played","wanted"],"answer":2,"why":"want 末尾是 /t/，wanted 的 -ed 读 /ɪd/。","kind":"phonics","id":"u3-ph-q0"}]},"story":{"title":"The mummy’s tomb","pages":[38,39],"kind":"依据课文的教学改写","summary":"孩子们进入墓穴，先遇到蝎子，再因随意按按钮滑进地下。他们逃开木乃伊，在珍宝室遇到光门。","sentences":[{"en":"The children find a doorway covered with hieroglyphics.","zh":"孩子们找到一个布满象形文字的入口。","note":"covered with 表示被……覆盖。","id":"u3-story-s0"},{"en":"They disagree about whether the signs mean welcome or keep out.","zh":"他们对符号是“欢迎”还是“禁止入内”意见不一。","note":"whether … or … 表示究竟是……还是……。","id":"u3-story-s1"},{"en":"Patrick wants to enter, although Alex thinks it may be dangerous.","zh":"Patrick 想进去，尽管 Alex 觉得可能有危险。","note":"although 引出相反的想法。","id":"u3-story-s2"},{"en":"Inside the dark passage, small creatures fall onto the children.","zh":"在黑暗的通道里，小生物掉到了孩子们身上。","note":"passage 在这里指通道，不是文章段落。","id":"u3-story-s3"},{"en":"Alex recognises them as scorpions, and the children run away.","zh":"Alex 认出那是蝎子，孩子们跑开了。","note":"recognise … as … 是认出……是……。","id":"u3-story-s4"},{"en":"At the end of a corridor, Patrick presses a button without waiting.","zh":"在走廊尽头，Patrick 没有等待就按了一个按钮。","note":"without waiting 说明他没有先停下来判断。","id":"u3-story-s5"},{"en":"The floor opens, and they slide into a room deep inside the pyramid.","zh":"地板打开了，他们滑进金字塔深处的房间。","note":"slide 是滑行；deep inside 表示深处。","id":"u3-story-s6"},{"en":"A white figure comes towards them, and they believe it is a mummy.","zh":"一个白色身影走向他们，他们认为那是木乃伊。","note":"believe 描述人物的判断。","id":"u3-story-s7"},{"en":"They run into another room and block the doorway with a rock.","zh":"他们跑进另一个房间，用岩石堵住入口。","note":"with a rock 说明使用什么。","id":"u3-story-s8"},{"en":"Gold and silver objects shine around them in the beautiful tomb.","zh":"美丽的陵墓里，金银物品在四周闪耀。","note":"shine 是发光；tomb 是陵墓。","id":"u3-story-s9"},{"en":"Phoebe wants to look longer, but the yellow gate appears and they leave.","zh":"Phoebe 还想多看一会儿，但黄色光门出现了，他们便离开了。","note":"but 标明愿望与实际行动不同；冒险情节不可照做。","id":"u3-story-s10"}],"questions":[{"prompt":"孩子们为什么滑进金字塔深处？","options":["Patrick 按了按钮，地板打开了。","他们坐了电梯。","Phoebe 挖了一条新路。"],"answer":0,"why":"先按按钮，再地板打开，再滑下去，这是明确的因果链。","kind":"meaning","id":"u3-story-q0"},{"prompt":"Phoebe 在最后一个房间为什么改变了心情？","options":["她找到了学校铃。","她看见美丽的金银物品，想多停留。","她终于吃到午饭。"],"answer":1,"why":"她从害怕变成惊叹，是因为看到美丽的陵墓和珍宝。","kind":"meaning","id":"u3-story-q1"}]},"reading":{"title":"Rhodopis and the golden shoe","pages":[41],"kind":"依据课文的教学改写","summary":"这是教材收录的一则古埃及背景传说。Rhodopis 受到不公平对待，一只金鞋把她与法老的故事联系起来；传说不是历史事实记录。","sentences":[{"en":"In the legend, Rhodopis works as a servant in an old man's house.","zh":"在传说中，Rhodopis 在一位老人的家里做仆人。","note":"in the legend 明确这是一则传说。","id":"u3-reading-s0"},{"en":"The other girls are unkind because she looks different from them.","zh":"其他女孩因为她看起来不同，就对她不友善。","note":"because 说明她被不公平对待的原因。","id":"u3-reading-s1"},{"en":"Rhodopis feels lonely and talks to the animals near the river.","zh":"Rhodopis 感到孤单，向河边的动物说心事。","note":"lonely 是孤单的；不是一个人的错误。","id":"u3-reading-s2"},{"en":"The old man sees her dancing and gives her beautiful golden shoes.","zh":"老人看到她跳舞，送给她一双漂亮的金鞋。","note":"gives her … 表示送给她……。","id":"u3-reading-s3"},{"en":"When everyone is invited to the Pharaoh's party, the girls keep her working.","zh":"当大家受邀参加法老的聚会时，那些女孩却让她继续干活。","note":"keep someone doing 是让某人一直做某事。","id":"u3-reading-s4"},{"en":"A hippo splashes her shoes, so she leaves them in the sun to dry.","zh":"河马溅湿了她的鞋，因此她把鞋放在太阳下晒干。","note":"so 连接原因与结果。","id":"u3-reading-s5"},{"en":"A bird takes one shoe and drops it near the Pharaoh.","zh":"一只鸟叼走一只鞋，把它落在法老附近。","note":"one shoe 是一双中的一只。","id":"u3-reading-s6"},{"en":"The Pharaoh searches for the person who owns the shoe.","zh":"法老寻找那只鞋的主人。","note":"who owns the shoe 说明寻找谁。","id":"u3-reading-s7"},{"en":"When he reaches the house, the shoe fits Rhodopis.","zh":"当他来到那座房子时，鞋正好适合 Rhodopis。","note":"fit 在这里表示大小合适。","id":"u3-reading-s8"},{"en":"He chooses Rhodopis as his queen despite the other girls' objections.","zh":"尽管其他女孩反对，他还是选择 Rhodopis 做王后。","note":"despite 表示尽管；讨论时关注尊重差异与公平对待。","id":"u3-reading-s9"}],"questions":[{"prompt":"把金鞋带到法老那里的是谁？","options":["河马。","一只鸟。","那几个女孩。"],"answer":1,"why":"河马溅湿鞋，鸟带走鞋；两个动作的执行者不同。","kind":"meaning","id":"u3-reading-q0"},{"prompt":"哪句话最符合这篇故事的价值讨论？","options":["外表不同就应该被排斥。","仆人没有感受。","每个人都应得到尊重和公平对待。"],"answer":2,"why":"故事里的不友善行为造成伤害，不能以外表或身份判断人的价值。","kind":"meaning","id":"u3-reading-q1"}]},"world":{"title":"Three-dimensional shapes","pages":[42,43],"kind":"依据课文的教学改写","summary":"从平面与立体的区别入手，认识面、棱和顶点，并用纸金字塔理解展开图。","sentences":[{"en":"A two-dimensional shape has length and width.","zh":"二维图形有长和宽。","note":"two-dimensional 可简称 2D。","id":"u3-world-s0"},{"en":"A three-dimensional shape also has height or depth.","zh":"三维形状还有高度或深度。","note":"also 表示比前面多一个维度。","id":"u3-world-s1"},{"en":"A cube has six square faces.","zh":"正方体有六个正方形面。","note":"face 在几何中是面，不是人的脸。","id":"u3-world-s2"},{"en":"An edge is where two faces meet, and a vertex is a corner.","zh":"棱是两个面相接的地方，顶点就是角点。","note":"edge、vertex 是观察形状的关键词。","id":"u3-world-s3"},{"en":"A square-based pyramid has one square base and four triangular faces.","zh":"四棱锥有一个正方形底面和四个三角形侧面。","note":"square-based 说明底面形状。","id":"u3-world-s4"},{"en":"The four triangular faces meet at one top point.","zh":"四个三角形侧面在顶部的一个点相会。","note":"meet 表示相交、相接。","id":"u3-world-s5"},{"en":"A cylinder has two circular flat faces and one curved surface.","zh":"圆柱有两个圆形平面和一个曲面。","note":"flat 与 curved 分别是平的和弯曲的。","id":"u3-world-s6"},{"en":"A paper net can be folded to make a model of a solid shape.","zh":"纸展开图可以折成立体模型。","note":"net 在这里是展开图，与球网的意思不同。","id":"u3-world-s7"}],"questions":[{"prompt":"正方体有几个正方形面？","options":["四个。","六个。","八个。"],"answer":1,"why":"cube 有六个面；八个是它的顶点数，别混淆。","kind":"meaning","id":"u3-world-q0"},{"prompt":"四棱锥的底面是什么形状？","options":["正方形。","圆形。","五边形。"],"answer":0,"why":"square-based 已经说明它有一个正方形底面。","kind":"meaning","id":"u3-world-q1"}]},"create":{"title":"古代文明小讲解员","pages":[43,44,45],"tasks":["选古埃及或另一个熟悉的古代文明，画一张图并标出 3 个英文词。","准备三条可在教材或可靠图书中找到的事实，并记录来源页码。","用约一分钟介绍地点、一个代表物及其特点；可以展示纸模型。"],"frame":"My topic is …\nThe people lived in …\nThey are known for …\nThis model was made from …\nIt has … faces.\nOne question I still have is …","model":"My topic is Ancient Egypt. The pyramids are famous buildings. This is my paper model of a square-based pyramid. It was made from paper and tape. It has one square base and four triangular faces. I would like to learn more about the writing on ancient walls.","success":"区分事实与猜想；至少用一句被动语态，一处形状词，并能指出信息来源。","teacher":"对应第 43 页纸模型与第 44 页古代文明演讲；不采用旧版“所有金字塔均由奴隶建造”等简化表述。"},"questions":[{"prompt":"The paper pyramid ___ made yesterday.","options":["were","was","has"],"answer":1,"why":"pyramid 是单数，过去时被动语态用 was made。","kind":"grammar","id":"u3-g0-q0"},{"prompt":"The stones were ___ to the museum.","options":["take","taking","taken"],"answer":2,"why":"被动语态用过去分词，take 的过去分词是 taken。","kind":"grammar","id":"u3-g0-q1"},{"prompt":"We have ___ small stones.","options":["a few","a little","much a"],"answer":0,"why":"stones 可数且为复数，表示几个用 a few。","kind":"grammar","id":"u3-g1-q0"},{"prompt":"There is ___ water in the cup.","options":["a few","a little","many"],"answer":1,"why":"water 是不可数名词，表示一点用 a little。","kind":"grammar","id":"u3-g1-q1"},{"prompt":"孩子们为什么滑进金字塔深处？","options":["Patrick 按了按钮，地板打开了。","他们坐了电梯。","Phoebe 挖了一条新路。"],"answer":0,"why":"先按按钮，再地板打开，再滑下去，这是明确的因果链。","kind":"meaning","id":"u3-story-q0"},{"prompt":"Phoebe 在最后一个房间为什么改变了心情？","options":["她找到了学校铃。","她看见美丽的金银物品，想多停留。","她终于吃到午饭。"],"answer":1,"why":"她从害怕变成惊叹，是因为看到美丽的陵墓和珍宝。","kind":"meaning","id":"u3-story-q1"},{"prompt":"把金鞋带到法老那里的是谁？","options":["河马。","一只鸟。","那几个女孩。"],"answer":1,"why":"河马溅湿鞋，鸟带走鞋；两个动作的执行者不同。","kind":"meaning","id":"u3-reading-q0"},{"prompt":"哪句话最符合这篇故事的价值讨论？","options":["外表不同就应该被排斥。","仆人没有感受。","每个人都应得到尊重和公平对待。"],"answer":2,"why":"故事里的不友善行为造成伤害，不能以外表或身份判断人的价值。","kind":"meaning","id":"u3-reading-q1"},{"prompt":"正方体有几个正方形面？","options":["四个。","六个。","八个。"],"answer":1,"why":"cube 有六个面；八个是它的顶点数，别混淆。","kind":"meaning","id":"u3-world-q0"},{"prompt":"四棱锥的底面是什么形状？","options":["正方形。","圆形。","五边形。"],"answer":0,"why":"square-based 已经说明它有一个正方形底面。","kind":"meaning","id":"u3-world-q1"},{"prompt":"哪一个词的 -ed 读 /ɪd/，增加一个音节？","options":["looked","played","wanted"],"answer":2,"why":"want 末尾是 /t/，wanted 的 -ed 读 /ɪd/。","kind":"phonics","id":"u3-ph-q0"}]},{"id":4,"title":"Olympic sports","zh":"奥运运动","start":46,"end":57,"icon":"🏅","goal":"提出并回应建议，说明已安排的计划，按线索复述赛场经历。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":122,"vocab":[{"word":"long jump","zh":"跳远","example":"We watched the long jump at school."},{"word":"gymnastics","zh":"体操","example":"She practises gymnastics with her coach."},{"word":"rowing","zh":"赛艇运动","example":"The rowing team trains on the lake."},{"word":"archery","zh":"射箭","example":"We saw an archery competition on TV."},{"word":"high jump","zh":"跳高","example":"The high jump starts at ten."},{"word":"wrestling","zh":"摔跤","example":"The wrestling match was exciting."},{"word":"hurdles","zh":"跨栏","example":"The runner cleared the hurdles."},{"word":"weightlifting","zh":"举重","example":"Weightlifting needs careful training."},{"word":"fencing","zh":"击剑","example":"The fencing team wears special equipment."},{"word":"boxing","zh":"拳击","example":"The poster shows a boxing match."}],"grammar":[{"title":"We could … ：提出建议","rule":"could + 动词原形，可委婉提出建议。用 Sounds good. 接受，用 I’m not too keen on that. 温和表达不太喜欢。","examples":[{"en":"We could watch the rowing.","zh":"我们可以看赛艇。"},{"en":"We could go after lunch.","zh":"我们可以午饭后去。"}],"questions":[{"prompt":"We could ___ the high jump.","options":["watching","watched","watch"],"answer":2,"why":"情态动词 could 后接原形 watch。","kind":"grammar","id":"u4-g0-q0"},{"prompt":"哪一句是友善地提出建议？","options":["You always make mistakes.","We could try the art club.","I went there yesterday."],"answer":1,"why":"We could … 是本单元建议句型。","kind":"grammar","id":"u4-g0-q1"}]},{"title":"现在进行时表示安排","rule":"be + 动词 -ing 配合 tomorrow、on Saturday 等时间词，可以表示已经安排好的将来活动。","examples":[{"en":"I am meeting my coach tomorrow.","zh":"我明天要见教练。"},{"en":"They are playing a match on Saturday.","zh":"他们周六要打一场比赛。"}],"questions":[{"prompt":"She ___ playing tennis tomorrow.","options":["is","are","does"],"answer":0,"why":"she 与 is 搭配，再接 playing。","kind":"grammar","id":"u4-g1-q0"},{"prompt":"“We are meeting at three tomorrow.” 表达什么？","options":["过去的经历","已经安排的会面","永远不变的习惯"],"answer":1,"why":"tomorrow 提示将来；现在进行时这里表示已安排的活动。","kind":"grammar","id":"u4-g1-q1"}]}],"song":{"title":"Saying that you are not interested：表达不感兴趣","page":48,"type":"dialogue","task":["在第 48 页找到 Olivia 的三个建议，并读出 Charlie 的回应。","任选两个课后活动，用 We could … 提建议，并补充真实理由。","练习不同意时保持礼貌，再共同选一个双方都愿意的活动。"]},"extra":[],"phonics":{"title":"按意群读：建议与回应","note":"依据第 47–48 页对话新编。could 后紧接动词，重读活动名称；礼貌回应可以分成“先表态 / 再解释”两块。","pairs":[{"a":"We could watch rowing.","b":"Sounds good to me."},{"a":"I am not too keen on that.","b":"What about tennis?"},{"a":"Sorry, but I cannot swim.","b":"We could choose another club."}],"page":48,"questions":[{"prompt":"朗读 We could watch the rowing. 时，could 后应接哪个形式？","options":["watch","watched","watching"],"answer":0,"why":"could 后跟动词原形；连贯读 could watch。","kind":"phonics","id":"u4-ph-q0"}]},"story":{"title":"Not the best day","pages":[50,51],"kind":"依据课文的教学改写","summary":"三场比赛带来三次意外：Phoebe 被球打到，Patrick 的脚受伤，Alex 掉进水里。找准人、地点、事件就能复述。","sentences":[{"en":"The friends take a bus to a hall near the Olympic Stadium.","zh":"朋友们乘巴士来到奥林匹克体育场附近的场馆。","note":"near 说明位置；先交代第一站。","id":"u4-story-s0"},{"en":"They sit in the front row to watch volleyball.","zh":"他们坐在前排看排球比赛。","note":"front row 是前排。","id":"u4-story-s1"},{"en":"Phoebe cheers excitedly, but a ball hits her face near the end.","zh":"Phoebe 兴奋地欢呼，但临近结束时球打到了她的脸。","note":"near the end 说明事情发生的时间。","id":"u4-story-s2"},{"en":"Her eye hurts, and the friends move on to a wrestling match.","zh":"她的眼睛受伤了，朋友们接着去看摔跤比赛。","note":"move on to 表示转到下一项活动。","id":"u4-story-s3"},{"en":"Patrick admires the shorter wrestler and expects him to win.","zh":"Patrick 欣赏个子较矮的选手，认为他会赢。","note":"expect someone to … 表示预料某人会……。","id":"u4-story-s4"},{"en":"The taller wrestler is thrown through the air and lands on Patrick's foot.","zh":"个子较高的选手被摔出去，落到了 Patrick 的脚上。","note":"is thrown 是被动语态。","id":"u4-story-s5"},{"en":"Next, they watch rowing from seats close to the water.","zh":"接着，他们坐在靠近水面的座位上看赛艇。","note":"next 标明第三场活动。","id":"u4-story-s6"},{"en":"Alex leans forward while cheering for the rowers.","zh":"Alex 一边为赛艇选手欢呼，一边向前倾。","note":"while 表示两个动作同时发生。","id":"u4-story-s7"},{"en":"Phoebe warns him, but he leans too far and falls in.","zh":"Phoebe 提醒他，可他倾得太靠前，掉进了水里。","note":"too far 是过度，解释意外原因。","id":"u4-story-s8"},{"en":"His friends help him out, and the three leave through the yellow gate.","zh":"朋友们帮助他出来，三人穿过黄色光门离开。","note":"help him out 在这里是帮他离开水面。","id":"u4-story-s9"},{"en":"One has a black eye, one has a sore foot, and one is soaking wet.","zh":"一个眼圈青了，一个脚痛，还有一个全身湿透。","note":"平行结构帮助把三个人的经历对应起来。","id":"u4-story-s10"}],"questions":[{"prompt":"谁在看摔跤时脚受了伤？","options":["Phoebe。","Patrick。","Alex。"],"answer":1,"why":"Phoebe 在排球场受伤；Patrick 在摔跤场伤脚；Alex 在赛艇场落水。","kind":"meaning","id":"u4-story-q0"},{"prompt":"Alex 为什么落水？","options":["他欢呼时身体向前倾得太多。","他被排球打落水。","他主动参加了赛艇比赛。"],"answer":0,"why":"文本说明他 lean forward 太远，注意不是其他两人的事故。","kind":"meaning","id":"u4-story-q1"}]},"reading":{"title":"Reading about the X Games","pages":[52],"kind":"依据课文的教学改写","summary":"用小标题快速读懂介绍性文章：是什么、有哪些项目、怎样观看。旧教材的赛事地点和项目分类不作为今日赛程信息。","sentences":[{"en":"The article introduces a sports event called the X Games.","zh":"文章介绍名叫 X Games 的体育赛事。","note":"introduces 是介绍；原文采用问答式小标题。","id":"u4-reading-s0"},{"en":"It groups its information under short questions.","zh":"它把信息放在简短的问题下面。","note":"under 在这里指小标题之下。","id":"u4-reading-s1"},{"en":"The photographs show sports such as skateboarding and BMX biking.","zh":"照片展示了滑板和小轮车等运动。","note":"such as 表示举例，不是列出全部。","id":"u4-reading-s2"},{"en":"Other examples include snowboarding and snowmobiling.","zh":"其他例子包括单板滑雪和雪地摩托。","note":"include 表示包括。","id":"u4-reading-s3"},{"en":"The article describes separate events for summer and winter sports.","zh":"文章描述了分别面向夏季和冬季运动的赛事。","note":"separate 表示分开的。","id":"u4-reading-s4"},{"en":"Competitors aim to win medals, and the audience watches their skills.","zh":"参赛者争取奖牌，观众欣赏他们的技巧。","note":"competitors 与 audience 分别是参赛者和观众。","id":"u4-reading-s5"},{"en":"The text also mentions music and meeting other sports fans.","zh":"文章还提到音乐和与其他体育爱好者见面。","note":"also 告诉我们活动不只有比赛。","id":"u4-reading-s6"},{"en":"A final section explains that people can watch without attending in person.","zh":"最后一部分说明，人们不亲临现场也可以观看。","note":"in person 是亲自到场。","id":"u4-reading-s7"},{"en":"The headings help a reader find the answer to a specific question.","zh":"这些小标题帮助读者找到某个具体问题的答案。","note":"specific 表示具体的；先确定问题再定位段落。","id":"u4-reading-s8"}],"questions":[{"prompt":"想知道文中有哪些比赛项目，应先找哪类小标题？","options":["What sports do they do?","When is your birthday?","Who wrote this poem?"],"answer":0,"why":"项目问题与 What sports … 对应，能快速定位信息。","kind":"meaning","id":"u4-reading-q0"},{"prompt":"文章最后一部分主要解决什么问题？","options":["如何制作奖牌。","怎样不去现场也观看比赛。","谁发明了所有运动。"],"answer":1,"why":"最后一节是 What if I can’t go?，介绍远程观看方式。","kind":"meaning","id":"u4-reading-q1"}]},"world":{"title":"Muscles help us move","pages":[54,55],"kind":"依据课文的教学改写","summary":"肌肉让身体运动，有些能有意识控制，有些自动工作。理解基本概念，再用一份简单活动记录练英语。","sentences":[{"en":"Muscles help our bodies move in many different ways.","zh":"肌肉帮助身体以许多不同方式运动。","note":"move 是移动或活动，不只指跑步。","id":"u4-world-s0"},{"en":"We use muscles when we walk, smile and eat.","zh":"走路、微笑和吃东西时，我们都会用到肌肉。","note":"when 介绍使用肌肉的场景。","id":"u4-world-s1"},{"en":"Many muscles are connected to the bones of the skeleton.","zh":"许多肌肉与骨骼相连接。","note":"skeleton 是骨骼系统。","id":"u4-world-s2"},{"en":"We can choose to move voluntary muscles, such as those in our fingers.","zh":"我们能有意识地控制随意肌，例如手指运动所用的肌肉。","note":"voluntary 在这里指可有意识控制。","id":"u4-world-s3"},{"en":"Other muscles work without us deciding each movement.","zh":"另一些肌肉工作时，不需要我们决定每一个动作。","note":"without … deciding 表示不必有意识地下达每次动作。","id":"u4-world-s4"},{"en":"Our heart keeps beating while we think about other things.","zh":"当我们想着别的事情时，心脏仍然在跳动。","note":"keeps beating 是持续跳动。","id":"u4-world-s5"},{"en":"Muscles need energy, which our bodies get from food.","zh":"肌肉需要能量，而身体从食物中获得能量。","note":"which 指代前面的 energy。","id":"u4-world-s6"},{"en":"Different activities use different groups of muscles.","zh":"不同活动会使用不同的肌群。","note":"different … different … 是这段的比较重点。","id":"u4-world-s7"}],"questions":[{"prompt":"哪一种活动是能主动决定的肌肉运动例子？","options":["用手指写字。","要求心脏每一次跳动。","让所有肌肉永远停止。"],"answer":0,"why":"手指写字是教材用来说明随意肌的例子。","kind":"meaning","id":"u4-world-q0"},{"prompt":"文中为什么提到食物？","options":["食物让骨头消失。","身体从食物中获取肌肉所需的能量。","只要吃东西就不需要活动。"],"answer":1,"why":"食物与能量有关；文章没有说可以因此不活动。","kind":"meaning","id":"u4-world-q1"}]},"create":{"title":"体育记者的小采访","pages":[56,57],"tasks":["选择一个真实运动员或明确标为虚构的人物，准备 4 个采访问题。","至少问一个经历问题和一个未来安排问题。","分角色采访，再把听到的两条信息整理成短文，事实与虚构分清。"],"frame":"May I ask you some questions?\nWhen are you playing next?\nHave you ever … ?\nHow often do you practise?\nThank you for talking to me.","model":"This is an imaginary interview. Our tennis player is playing a match on Saturday. She practises three times a week. She has played in a school final, and she felt nervous before it. She likes tennis because she can learn from each match.","success":"能礼貌提问、认真听答复，并用现在进行时说明一项已安排的活动。","teacher":"对应第 56 页采访角色卡；示范人物为虚构，不声称教材音频中存在该采访。"},"questions":[{"prompt":"We could ___ the high jump.","options":["watching","watched","watch"],"answer":2,"why":"情态动词 could 后接原形 watch。","kind":"grammar","id":"u4-g0-q0"},{"prompt":"哪一句是友善地提出建议？","options":["You always make mistakes.","We could try the art club.","I went there yesterday."],"answer":1,"why":"We could … 是本单元建议句型。","kind":"grammar","id":"u4-g0-q1"},{"prompt":"She ___ playing tennis tomorrow.","options":["is","are","does"],"answer":0,"why":"she 与 is 搭配，再接 playing。","kind":"grammar","id":"u4-g1-q0"},{"prompt":"“We are meeting at three tomorrow.” 表达什么？","options":["过去的经历","已经安排的会面","永远不变的习惯"],"answer":1,"why":"tomorrow 提示将来；现在进行时这里表示已安排的活动。","kind":"grammar","id":"u4-g1-q1"},{"prompt":"谁在看摔跤时脚受了伤？","options":["Phoebe。","Patrick。","Alex。"],"answer":1,"why":"Phoebe 在排球场受伤；Patrick 在摔跤场伤脚；Alex 在赛艇场落水。","kind":"meaning","id":"u4-story-q0"},{"prompt":"Alex 为什么落水？","options":["他欢呼时身体向前倾得太多。","他被排球打落水。","他主动参加了赛艇比赛。"],"answer":0,"why":"文本说明他 lean forward 太远，注意不是其他两人的事故。","kind":"meaning","id":"u4-story-q1"},{"prompt":"想知道文中有哪些比赛项目，应先找哪类小标题？","options":["What sports do they do?","When is your birthday?","Who wrote this poem?"],"answer":0,"why":"项目问题与 What sports … 对应，能快速定位信息。","kind":"meaning","id":"u4-reading-q0"},{"prompt":"文章最后一部分主要解决什么问题？","options":["如何制作奖牌。","怎样不去现场也观看比赛。","谁发明了所有运动。"],"answer":1,"why":"最后一节是 What if I can’t go?，介绍远程观看方式。","kind":"meaning","id":"u4-reading-q1"},{"prompt":"哪一种活动是能主动决定的肌肉运动例子？","options":["用手指写字。","要求心脏每一次跳动。","让所有肌肉永远停止。"],"answer":0,"why":"手指写字是教材用来说明随意肌的例子。","kind":"meaning","id":"u4-world-q0"},{"prompt":"文中为什么提到食物？","options":["食物让骨头消失。","身体从食物中获取肌肉所需的能量。","只要吃东西就不需要活动。"],"answer":1,"why":"食物与能量有关；文章没有说可以因此不活动。","kind":"meaning","id":"u4-world-q1"},{"prompt":"朗读 We could watch the rowing. 时，could 后应接哪个形式？","options":["watch","watched","watching"],"answer":0,"why":"could 后跟动词原形；连贯读 could watch。","kind":"phonics","id":"u4-ph-q0"}]},{"id":5,"title":"In London","zh":"伦敦之旅","start":58,"end":69,"icon":"🌉","goal":"先讲经历再补充时间细节，辨认伦敦景点与印象派画作。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":123,"vocab":[{"word":"chemist’s","zh":"药店","example":"The chemist’s is next to the station."},{"word":"tailor’s","zh":"裁缝店","example":"The tailor’s makes and repairs clothes."},{"word":"barber’s","zh":"理发店","example":"He went to the barber’s for a haircut."},{"word":"baker’s","zh":"面包店","example":"We bought fresh bread at the baker’s."},{"word":"grocer’s","zh":"食品杂货店","example":"The grocer’s sells fruit and vegetables."},{"word":"butcher’s","zh":"肉店","example":"There is a butcher’s on the high street."},{"word":"jeweller’s","zh":"珠宝店","example":"The jeweller’s displays rings in the window."},{"word":"carpenter’s","zh":"木匠作坊","example":"The carpenter’s has wooden chairs."}],"grammar":[{"title":"Have you ever … ? / never","rule":"Have / Has + 主语 + ever + 过去分词，询问到现在为止有没有某经历。never 表示从未，不再加 not。","examples":[{"en":"Have you ever visited a castle?","zh":"你曾参观过城堡吗？"},{"en":"I have never seen a wax figure.","zh":"我从未见过蜡像。"}],"questions":[{"prompt":"Have you ever ___ to London?","options":["go","been","went"],"answer":1,"why":"现在完成时用过去分词 been。","kind":"grammar","id":"u5-g0-q0"},{"prompt":"她从未去过那儿：She has ___ been there.","options":["never","not never","no"],"answer":0,"why":"never 已含否定，不用 not never。","kind":"grammar","id":"u5-g0-q1"}]},{"title":"经历与具体过去时间","rule":"现在完成时谈经历；出现 yesterday、last week 等明确过去时间时，用一般过去时补充细节。","examples":[{"en":"I have been to the museum.","zh":"我去过那家博物馆。"},{"en":"I went there with my aunt last week.","zh":"我上周和阿姨去的。"}],"questions":[{"prompt":"Have you seen the bridge? — Yes, I ___ it yesterday.","options":["have seen","will see","saw"],"answer":2,"why":"yesterday 指明确的过去时间，用 saw。","kind":"grammar","id":"u5-g1-q0"},{"prompt":"哪一句自然地补充过去的细节？","options":["I visited it last Sunday.","I have visited it yesterday.","I visit it tomorrow yesterday."],"answer":0,"why":"last Sunday 应与一般过去时 visited 搭配。","kind":"grammar","id":"u5-g1-q1"}]}],"song":{"title":"Have you … ?","page":60,"type":"song","task":["在第 60 页歌词中找到 London、Paris、New York。","把 Have you ever … ? 读成完整问题，再给一个真实回答。","如果回答 Yes，补充 I went … / I saw … 和一个具体时间。"]},"extra":[],"phonics":{"title":"/s/ 与 /z/：声音是否振动","note":"对应第 60 页。/s/ 像轻轻的嘶声，/z/ 发音时声带振动；相同字母 s 不一定发相同的音。","pairs":[{"a":"city","b":"zoo"},{"a":"hissing","b":"buzzing"},{"a":"snake","b":"bees"}],"page":60,"questions":[{"prompt":"哪个词开头是 /z/？","options":["snake","city","zoo"],"answer":2,"why":"zoo 的开头是 /z/；snake、city 的开头是 /s/。","kind":"phonics","id":"u5-ph-q0"}]},"story":{"title":"The Great Fire","pages":[62,63],"kind":"依据课文的教学改写","summary":"孩子们在 1666 年伦敦大火的虚构穿越故事中帮助他人。Fisher 一家放下家具腾出位置，让更多孩子安全离开。","sentences":[{"en":"The children meet Mr Fisher while a great fire spreads through London.","zh":"当一场大火在伦敦蔓延时，孩子们遇到 Fisher 先生。","note":"spreads through 表示蔓延；这是历史背景中的虚构冒险。","id":"u5-story-s0"},{"en":"He explains that the fire started at a baker's and grew in the strong wind.","zh":"他说火起于面包店，强风使火势扩大。","note":"grew 在这里指火势变大。","id":"u5-story-s1"},{"en":"Mr Fisher wants to take his family to the countryside in a cart.","zh":"Fisher 先生想用马车带家人到乡下。","note":"take … to … 是把……带到……。","id":"u5-story-s2"},{"en":"Beside the river, people hurry to load their belongings onto boats.","zh":"河边，人们急忙把物品装到船上。","note":"belongings 是个人物品。","id":"u5-story-s3"},{"en":"A small child falls into the water when a crowded boat rocks.","zh":"一艘拥挤的船晃动时，一个小孩掉进水里。","note":"when 说明落水发生的情境。","id":"u5-story-s4"},{"en":"In the story, Patrick brings the child back, and the mother gives him a bracelet.","zh":"故事里 Patrick 把孩子救回，母亲送给他一只手镯。","note":"手镯是本册结尾再次出现的重要线索；现实水上救援需专业帮助。","id":"u5-story-s5"},{"en":"At Mr Fisher's house, the friends help load a large chest onto the cart.","zh":"在 Fisher 先生家，朋友们帮助把一个大箱子装上马车。","note":"load … onto … 是把……装到……上。","id":"u5-story-s6"},{"en":"A woman arrives with tired children who also need to escape.","zh":"一位女人带着一些疲惫的孩子赶到，他们也需要逃离。","note":"who 引出这些孩子的情况。","id":"u5-story-s7"},{"en":"The family removes furniture to make room for more people.","zh":"这家人搬下家具，为更多的人腾出位置。","note":"make room 表示腾位置，room 在这里不可数。","id":"u5-story-s8"},{"en":"The friends give up their places and let the other children ride.","zh":"三个朋友让出自己的位置，让其他孩子乘车。","note":"give up 在这里是让出，不是对学习失去信心。","id":"u5-story-s9"},{"en":"A yellow light shines in the doorway, and the friends use their magical way out.","zh":"门口亮起黄光，朋友们用自己的魔法通道离开。","note":"magical 明确这是虚构的逃离方式。","id":"u5-story-s10"}],"questions":[{"prompt":"Fisher 一家为什么把家具搬下车？","options":["家具需要重新油漆。","为了给需要离开的孩子腾出地方。","他们要在街上开商店。"],"answer":1,"why":"他们把人的安全放在物品前面，腾出车上空间。","kind":"meaning","id":"u5-story-q0"},{"prompt":"Patrick 得到的哪件物品会成为后面的线索？","options":["一只手镯。","一个足球。","一副滑雪板。"],"answer":0,"why":"小孩的母亲给了他 bracelet；末单元会再次出现。","kind":"meaning","id":"u5-story-q1"}]},"reading":{"title":"Four London sights","pages":[64],"kind":"依据课文的教学改写","summary":"把四个景点与各自特点配对：伦敦塔、塔桥、伦敦眼和蜡像馆。不学习旧版票价、排队时间或开放安排。","sentences":[{"en":"The textbook introduces four places that visitors can learn about in London.","zh":"教材介绍了四个可供了解的伦敦地点。","note":"four places 提醒我们建四栏来整理信息。","id":"u5-reading-s0"},{"en":"The Tower of London has been used as both a castle and a prison.","zh":"伦敦塔曾被用作城堡和监狱。","note":"both … and … 连接两种不同用途。","id":"u5-reading-s1"},{"en":"Its famous objects include the Crown Jewels.","zh":"那里著名的物品包括王室珠宝。","note":"include 表示包括，不代表只有这一类展品。","id":"u5-reading-s2"},{"en":"The reading also mentions the guards and the ravens at the Tower.","zh":"文章还提到伦敦塔的守卫和渡鸦。","note":"ravens 是鸟；注意与 Tower Bridge 分开。","id":"u5-reading-s3"},{"en":"Tower Bridge has sections that can be raised for passing ships.","zh":"塔桥有可以抬起、让船通过的部分。","note":"can be raised 是能够被抬起。","id":"u5-reading-s4"},{"en":"The London Eye is a large wheel with glass observation capsules.","zh":"伦敦眼是带有玻璃观景舱的大型摩天轮。","note":"observation 表示观察、观景。","id":"u5-reading-s5"},{"en":"From a capsule, visitors can look across the city.","zh":"游客从观景舱里可以俯瞰城市。","note":"across the city 表示看到城市的大片区域。","id":"u5-reading-s6"},{"en":"Madame Tussauds displays figures of famous people made from wax.","zh":"杜莎夫人蜡像馆展示用蜡制作的名人模型。","note":"made from wax 说明材料。","id":"u5-reading-s7"},{"en":"A wax figure may look real, but it is not the person standing there.","zh":"蜡像可能看起来很真，但并不是真人站在那里。","note":"may look 与 is not 区分外观和事实。","id":"u5-reading-s8"}],"questions":[{"prompt":"哪一个景点的部分结构可以抬起让船通过？","options":["London Eye。","Tower Bridge。","Madame Tussauds。"],"answer":1,"why":"raise 与 passing ships 是塔桥的关键特点。","kind":"meaning","id":"u5-reading-q0"},{"prompt":"蜡像馆里“名人”的真实身份是什么？","options":["用蜡做的人物模型。","正在工作的真正演员。","所有人都是守卫。"],"answer":0,"why":"made from wax 明确说明是蜡像，不能把外表当作事实。","kind":"meaning","id":"u5-reading-q1"}]},"world":{"title":"Impressionism: looking at light","pages":[66,67],"kind":"依据课文的教学改写","summary":"比较写实画与印象派，观察光、颜色和笔触。表达自己的观察时，要说明画中看见了什么。","sentences":[{"en":"Realistic paintings often show clear details that resemble real life.","zh":"写实绘画常呈现接近真实生活的清晰细节。","note":"resemble 是像、与……相似。","id":"u5-world-s0"},{"en":"Impressionist artists explored light, colour and the feeling of a scene.","zh":"印象派艺术家探索光线、颜色和场景带来的感受。","note":"scene 是画面或场景。","id":"u5-world-s1"},{"en":"The movement developed in France in the nineteenth century.","zh":"这一艺术运动于十九世纪在法国发展起来。","note":"nineteenth century 是 1801–1900 年这一世纪。","id":"u5-world-s2"},{"en":"Monet, Renoir, Degas and Pissarro are artists named in the textbook.","zh":"教材列出的艺术家有 Monet、Renoir、Degas 和 Pissarro。","note":"先认识姓名，不必一次背完拼写。","id":"u5-world-s3"},{"en":"Many artists painted outdoor scenes and everyday people.","zh":"许多艺术家画户外场景和普通人的生活。","note":"everyday 作形容词，意为日常的。","id":"u5-world-s4"},{"en":"They used short brush strokes to create effects of colour and light.","zh":"他们用短笔触创造色彩和光线的效果。","note":"brush strokes 是笔触。","id":"u5-world-s5"},{"en":"Close up, we may notice separate marks of paint.","zh":"近看时，我们可能注意到一块块独立的颜料痕迹。","note":"close up 表示靠近观察。","id":"u5-world-s6"},{"en":"From farther away, the marks can form a clearer whole scene.","zh":"从远些的位置看，这些笔触能形成更完整清晰的景象。","note":"whole scene 是整体画面。","id":"u5-world-s7"}],"questions":[{"prompt":"印象派画家特别关注什么？","options":["只画完全一样的直线。","光、色彩与场景感受。","隐藏每一笔颜料。"],"answer":1,"why":"光线、色彩和整体感受是本段的核心。","kind":"meaning","id":"u5-world-q0"},{"prompt":"为什么可以从不同距离看同一幅画？","options":["近看笔触，远看整体画面。","距离能改变画的作者。","远看一定会听见原曲。"],"answer":0,"why":"文中最后两句比较了近处与远处的观察。","kind":"meaning","id":"u5-world-q1"}]},"create":{"title":"为朋友做一张城市明信片","pages":[68,69],"tasks":["选一个了解的城市，整理两处景点或地点的特点。","用 Have you ever … ? 问家人，再写自己真实或明确虚构的旅行经历。","完成 5–7 句明信片，包含经历、具体过去时间和个人感受。"],"frame":"Hi …,\nGreetings from … !\nI have visited …\nYesterday, I …\nMy favourite place was … because …\nSee you soon!","model":"Hi Sam, Greetings from my imaginary trip to London! I have seen Tower Bridge. Yesterday, I visited a museum with my family. I liked the old objects because each one had a story. I have taken some photographs too. See you soon!","success":"清楚区分真实与虚构；现在完成时讲经历，一般过去时补充具体时间，并给出一个理由。","teacher":"依据第 68 页城市介绍及第 69 页明信片写作新编；不虚构任何真实的个人旅行。"},"questions":[{"prompt":"Have you ever ___ to London?","options":["go","been","went"],"answer":1,"why":"现在完成时用过去分词 been。","kind":"grammar","id":"u5-g0-q0"},{"prompt":"她从未去过那儿：She has ___ been there.","options":["never","not never","no"],"answer":0,"why":"never 已含否定，不用 not never。","kind":"grammar","id":"u5-g0-q1"},{"prompt":"Have you seen the bridge? — Yes, I ___ it yesterday.","options":["have seen","will see","saw"],"answer":2,"why":"yesterday 指明确的过去时间，用 saw。","kind":"grammar","id":"u5-g1-q0"},{"prompt":"哪一句自然地补充过去的细节？","options":["I visited it last Sunday.","I have visited it yesterday.","I visit it tomorrow yesterday."],"answer":0,"why":"last Sunday 应与一般过去时 visited 搭配。","kind":"grammar","id":"u5-g1-q1"},{"prompt":"Fisher 一家为什么把家具搬下车？","options":["家具需要重新油漆。","为了给需要离开的孩子腾出地方。","他们要在街上开商店。"],"answer":1,"why":"他们把人的安全放在物品前面，腾出车上空间。","kind":"meaning","id":"u5-story-q0"},{"prompt":"Patrick 得到的哪件物品会成为后面的线索？","options":["一只手镯。","一个足球。","一副滑雪板。"],"answer":0,"why":"小孩的母亲给了他 bracelet；末单元会再次出现。","kind":"meaning","id":"u5-story-q1"},{"prompt":"哪一个景点的部分结构可以抬起让船通过？","options":["London Eye。","Tower Bridge。","Madame Tussauds。"],"answer":1,"why":"raise 与 passing ships 是塔桥的关键特点。","kind":"meaning","id":"u5-reading-q0"},{"prompt":"蜡像馆里“名人”的真实身份是什么？","options":["用蜡做的人物模型。","正在工作的真正演员。","所有人都是守卫。"],"answer":0,"why":"made from wax 明确说明是蜡像，不能把外表当作事实。","kind":"meaning","id":"u5-reading-q1"},{"prompt":"印象派画家特别关注什么？","options":["只画完全一样的直线。","光、色彩与场景感受。","隐藏每一笔颜料。"],"answer":1,"why":"光线、色彩和整体感受是本段的核心。","kind":"meaning","id":"u5-world-q0"},{"prompt":"为什么可以从不同距离看同一幅画？","options":["近看笔触，远看整体画面。","距离能改变画的作者。","远看一定会听见原曲。"],"answer":0,"why":"文中最后两句比较了近处与远处的观察。","kind":"meaning","id":"u5-world-q1"},{"prompt":"哪个词开头是 /z/？","options":["snake","city","zoo"],"answer":2,"why":"zoo 的开头是 /z/；snake、city 的开头是 /s/。","kind":"phonics","id":"u5-ph-q0"}]},{"id":6,"title":"Crazy inventions","zh":"奇妙发明","start":70,"end":81,"icon":"🛠️","goal":"描述发明的问题，礼貌询问机器用途，并解释杠杆的三个要素。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":124,"vocab":[{"word":"spanner","zh":"扳手","example":"The mechanic used a spanner."},{"word":"switch","zh":"开关","example":"The switch is beside the screen."},{"word":"lever","zh":"杠杆；操纵杆","example":"A lever turns around a pivot."},{"word":"button","zh":"按钮","example":"This button starts the toy."},{"word":"drill","zh":"钻；电钻","example":"The adult put the drill away safely."},{"word":"screwdriver","zh":"螺丝刀","example":"The screwdriver is in the toolbox."},{"word":"workbench","zh":"工作台","example":"The model is on the workbench."},{"word":"hammer","zh":"锤子","example":"The carpenter keeps the hammer on a shelf."},{"word":"saw","zh":"锯","example":"The adult uses a saw in the workshop."},{"word":"paintbrush","zh":"画笔；刷子","example":"My paintbrush has blue paint on it."}],"grammar":[{"title":"too many / not enough","rule":"too many + 可数复数表示太多；not enough + 可数复数或不可数名词表示不足。判断时要联系用途。","examples":[{"en":"This model has too many wheels.","zh":"这个模型的轮子太多了。"},{"en":"We have not got enough paper.","zh":"我们的纸不够。"}],"questions":[{"prompt":"The box is full. There are ___ books in it.","options":["too many","not enough","a little"],"answer":0,"why":"箱子已满，结合语境表示书太多。","kind":"grammar","id":"u6-g0-q0"},{"prompt":"We need four wheels, but we have two. We have ___ wheels.","options":["too many","not enough","too much"],"answer":1,"why":"需要四个却只有两个，说明数量不足。","kind":"grammar","id":"u6-g0-q1"}]},{"title":"Can you tell me … ?","rule":"礼貌问句中，后半句用陈述语序：what this machine is / what this lever does。不要再次把 is / does 提前。","examples":[{"en":"Can you tell me what this button does?","zh":"你能告诉我这个按钮有什么作用吗？"},{"en":"Can you tell me what this machine is for?","zh":"你能告诉我这台机器是做什么的吗？"}],"questions":[{"prompt":"Can you tell me ___?","options":["what does this lever","what this lever does","what do this lever"],"answer":1,"why":"嵌入问句保持主语 this lever 在谓语 does 前。","kind":"grammar","id":"u6-g1-q0"},{"prompt":"选择正确的礼貌问句。","options":["Can you tell me what is this machine?","Can you tell me what this machine is?","Can you tell me what this machine are?"],"answer":1,"why":"用 what this machine is 的陈述语序。","kind":"grammar","id":"u6-g1-q1"}]}],"song":{"title":"Giving reasons：说明理由","page":72,"type":"dialogue","task":["读第 72 页，解释模型为什么有四片机翼、为什么没有轮子。","圈出 That’s because … / That’s why …，各造一句有因果关系的句子。","画一个纸上发明，伙伴问用途，你用礼貌问句和理由回答。"]},"extra":[],"phonics":{"title":"原因意群：That is because …","note":"依据第 72 页功能对话新编。先说观察到的现象，稍停，再用 because 引出原因；不要把原因与结果颠倒。","pairs":[{"a":"It has no wheels.","b":"That is because it lands on water."},{"a":"It is mostly green.","b":"That is why we need green paint."},{"a":"I am hungry.","b":"Could you make a sandwich?"}],"page":72,"questions":[{"prompt":"“It lands on water. That is why it has no wheels.” 哪个是原因？","options":["没有轮子","它降落在水面上","有人饿了"],"answer":1,"why":"That is why 后引出结果；前面的降落地点是原因。","kind":"phonics","id":"u6-ph-q0"}]},"story":{"title":"Professor Potts","pages":[74,75],"kind":"依据课文的教学改写","summary":"教授的几台发明接连出错：上错颜色、算错题、传送出问题。Patrick 又碰了未完成的机器，黄色光门随之出现。","sentences":[{"en":"Professor Potts proudly shows the children his inventions.","zh":"Potts 教授骄傲地向孩子们展示发明。","note":"proudly 表示他展示时的心情。","id":"u6-story-s0"},{"en":"His painting machine should paint a chair with red and yellow spots.","zh":"他的涂色机器本应给椅子涂上红黄斑点。","note":"should 在这里表示预期效果。","id":"u6-story-s1"},{"en":"Instead, it covers the cat with green and blue spots.","zh":"结果，它把猫涂上了绿色和蓝色斑点。","note":"instead 引出与预期相反的结果。","id":"u6-story-s2"},{"en":"Next, the professor introduces a machine called Homework Express.","zh":"接着，教授介绍名叫 Homework Express 的作业机器。","note":"called 说明机器的名称。","id":"u6-story-s3"},{"en":"Alex gives it a large multiplication problem, but the answer looks wrong.","zh":"Alex 给它一道大数乘法题，但答案看起来不对。","note":"multiplication 是乘法；不要盲信机器答案。","id":"u6-story-s4"},{"en":"Another invention is supposed to move objects from one place to another.","zh":"另一项发明本应把物品从一个地方传到另一个地方。","note":"is supposed to 表示设计上应该做到。","id":"u6-story-s5"},{"en":"The professor tries his bicycle, and the attempt produces black smoke and a problem.","zh":"教授拿自行车试验，结果冒出黑烟，还出了问题。","note":"attempt 是一次尝试；观察结果是否符合目标。","id":"u6-story-s6"},{"en":"Phoebe declines a turn under the hairdressing machine.","zh":"Phoebe 拒绝试用理发机器。","note":"declines 表示礼貌拒绝。","id":"u6-story-s7"},{"en":"Patrick pulls a lever on an invention that is not finished.","zh":"Patrick 拉动了一台尚未完工机器的操纵杆。","note":"not finished 是解释风险的重要信息。","id":"u6-story-s8"},{"en":"The professor cannot explain the yellow light that appears.","zh":"教授无法解释突然出现的黄光。","note":"that appears 描述是哪道光。","id":"u6-story-s9"},{"en":"The children recognise their gate, say goodbye and step through it.","zh":"孩子们认出那是光门，道别后走了进去。","note":"recognise 表示再次认出熟悉的事物。","id":"u6-story-s10"}],"questions":[{"prompt":"涂色机器的实际结果与预期有什么不同？","options":["它正确涂好了椅子。","它涂到了猫身上，而且颜色也错了。","它把全部作业写完了。"],"answer":1,"why":"比较 should paint 与 instead 后的内容即可发现两个错误。","kind":"meaning","id":"u6-story-q0"},{"prompt":"为什么 Phoebe 不想试理发机器？","options":["她已看见其他机器出错，对可靠性有疑问。","她完全没看到任何发明。","她想让 Patrick 剪头发。"],"answer":0,"why":"这是依据前面接连出错作出的合理推断；不是把机器介绍当作可靠保证。","kind":"meaning","id":"u6-story-q1"}]},"reading":{"title":"Five inventions and their effects","pages":[76],"kind":"依据课文的教学改写","summary":"阅读五种发明怎样改变通信、出行、娱乐与工作。重点是功能与影响，不把旧版“最伟大”排名当作客观结论。","sentences":[{"en":"The webpage in the textbook chooses five important inventions.","zh":"教材里的网页选出了五种重要发明。","note":"chooses 表示这是作者的选择和观点。","id":"u6-reading-s0"},{"en":"They are the radio, the plane, the television, the computer and the mobile phone.","zh":"它们是收音机、飞机、电视、计算机和手机。","note":"先列出五种对象，有助于分组记忆。","id":"u6-reading-s1"},{"en":"Radio helps people send information across long distances.","zh":"无线电帮助人们远距离传递信息。","note":"across long distances 是跨越很远的距离。","id":"u6-reading-s2"},{"en":"Planes make many long journeys much faster.","zh":"飞机让许多长途旅行更快。","note":"make + 宾语 + 形容词，说明造成的变化。","id":"u6-reading-s3"},{"en":"Television brings moving pictures and sound into people's homes.","zh":"电视把动态画面与声音带进人们家中。","note":"moving pictures 指活动影像。","id":"u6-reading-s4"},{"en":"Computers help people process information and complete many kinds of work.","zh":"计算机帮助人们处理信息、完成多种工作。","note":"process 在这里是处理。","id":"u6-reading-s5"},{"en":"Mobile phones let people communicate away from a fixed telephone.","zh":"手机让人们不在固定电话旁也能联系。","note":"away from 表示离开某个地点。","id":"u6-reading-s6"},{"en":"Each invention can solve a problem, but it can also create new difficulties.","zh":"每种发明能解决问题，也可能带来新的困难。","note":"but 告诉我们还要考察另一面。","id":"u6-reading-s7"},{"en":"The best choice depends on the job that a person needs to do.","zh":"哪种最好，要看一个人需要完成什么任务。","note":"depends on 是取决于；评价需要标准。","id":"u6-reading-s8"}],"questions":[{"prompt":"文中哪一种发明主要让长途旅行更快？","options":["飞机。","油画。","课桌。"],"answer":0,"why":"Planes 对应 long journeys，功能与对象要配对。","kind":"meaning","id":"u6-reading-q0"},{"prompt":"如何更有依据地判断“哪个发明最好”？","options":["只看名字最长的是哪个。","先说明要解决的问题，再比较作用。","所有人必须永远选同一个。"],"answer":1,"why":"价值取决于任务和需求，不能只背一个排名。","kind":"meaning","id":"u6-reading-q1"}]},"world":{"title":"Levers: force, load and pivot","pages":[78,79],"kind":"依据课文的教学改写","summary":"以图片中的木杆搬木头为例，认识力、重物与支点。这里只观察原理，不需要操作真实工具或重物。","sentences":[{"en":"A lever is a simple machine that turns around a fixed point.","zh":"杠杆是绕一个固定点转动的简单机械。","note":"simple machine 是简单机械。","id":"u6-world-s0"},{"en":"The fixed point is called the pivot.","zh":"这个固定点叫支点。","note":"is called 是被称为。","id":"u6-world-s1"},{"en":"The object that we want to move is the load.","zh":"我们想移动的物体叫负载或重物。","note":"load 在这里是被移动的对象。","id":"u6-world-s2"},{"en":"A push or a pull applied to the lever is a force.","zh":"施加在杠杆上的推力或拉力是一种力。","note":"force 是力，不是机器的名称。","id":"u6-world-s3"},{"en":"In the picture, Gemma uses a pole resting on a rock.","zh":"图中 Gemma 用一根支在石头上的木杆。","note":"resting on 说明木杆支在什么上面。","id":"u6-world-s4"},{"en":"The rock is the pivot, and the heavy log is the load.","zh":"石头是支点，重木头是负载。","note":"把术语与具体对象配对。","id":"u6-world-s5"},{"en":"Pushing one end of the pole can lift the other end.","zh":"向下按木杆一端，可以抬起另一端。","note":"one end 与 the other end 是两端对比。","id":"u6-world-s6"},{"en":"The position of the pivot changes how much force is needed.","zh":"支点的位置会改变所需力的大小。","note":"position 是位置；这也是课本观察活动的重点。","id":"u6-world-s7"}],"questions":[{"prompt":"Gemma 的例子中，哪一个是支点？","options":["重木头。","石头。","她的帽子。"],"answer":1,"why":"木杆绕着石头支撑的位置转动，所以石头是 pivot。","kind":"meaning","id":"u6-world-q0"},{"prompt":"图中要被抬起的木头对应哪个词？","options":["load","screen","paint"],"answer":0,"why":"load 指要移动的负载，这里就是重木头。","kind":"meaning","id":"u6-world-q1"}]},"create":{"title":"纸上发明发布会","pages":[77,80,81],"tasks":["选一个日常小问题，画一台解决它的虚构机器；给按钮和操纵杆加标签。","写两句说明用途，再写一条还没解决的问题。","伙伴用 Can you tell me … ? 提问，你用 because 解释；只做绘画或纸模型。"],"frame":"My invention is called …\nIt helps people …\nThis button is for …\nIt has not got enough … yet.\nCan you tell me what … does?\nThat is because …","model":"My invention is a book-finding robot. It helps me find books on a tall shelf. The blue button starts a search. The red switch stops the machine. It has not got enough space for large books yet. I need to improve the design before it can work well.","success":"用途与按钮功能说清楚；能指出一条限制，正确使用一个间接问句和一个原因句。","teacher":"对应第 77 页创意发明、第 80 页询问材料与工具、第 81 页生动写作；活动限定为纸上设计。"},"questions":[{"prompt":"The box is full. There are ___ books in it.","options":["too many","not enough","a little"],"answer":0,"why":"箱子已满，结合语境表示书太多。","kind":"grammar","id":"u6-g0-q0"},{"prompt":"We need four wheels, but we have two. We have ___ wheels.","options":["too many","not enough","too much"],"answer":1,"why":"需要四个却只有两个，说明数量不足。","kind":"grammar","id":"u6-g0-q1"},{"prompt":"Can you tell me ___?","options":["what does this lever","what this lever does","what do this lever"],"answer":1,"why":"嵌入问句保持主语 this lever 在谓语 does 前。","kind":"grammar","id":"u6-g1-q0"},{"prompt":"选择正确的礼貌问句。","options":["Can you tell me what is this machine?","Can you tell me what this machine is?","Can you tell me what this machine are?"],"answer":1,"why":"用 what this machine is 的陈述语序。","kind":"grammar","id":"u6-g1-q1"},{"prompt":"涂色机器的实际结果与预期有什么不同？","options":["它正确涂好了椅子。","它涂到了猫身上，而且颜色也错了。","它把全部作业写完了。"],"answer":1,"why":"比较 should paint 与 instead 后的内容即可发现两个错误。","kind":"meaning","id":"u6-story-q0"},{"prompt":"为什么 Phoebe 不想试理发机器？","options":["她已看见其他机器出错，对可靠性有疑问。","她完全没看到任何发明。","她想让 Patrick 剪头发。"],"answer":0,"why":"这是依据前面接连出错作出的合理推断；不是把机器介绍当作可靠保证。","kind":"meaning","id":"u6-story-q1"},{"prompt":"文中哪一种发明主要让长途旅行更快？","options":["飞机。","油画。","课桌。"],"answer":0,"why":"Planes 对应 long journeys，功能与对象要配对。","kind":"meaning","id":"u6-reading-q0"},{"prompt":"如何更有依据地判断“哪个发明最好”？","options":["只看名字最长的是哪个。","先说明要解决的问题，再比较作用。","所有人必须永远选同一个。"],"answer":1,"why":"价值取决于任务和需求，不能只背一个排名。","kind":"meaning","id":"u6-reading-q1"},{"prompt":"Gemma 的例子中，哪一个是支点？","options":["重木头。","石头。","她的帽子。"],"answer":1,"why":"木杆绕着石头支撑的位置转动，所以石头是 pivot。","kind":"meaning","id":"u6-world-q0"},{"prompt":"图中要被抬起的木头对应哪个词？","options":["load","screen","paint"],"answer":0,"why":"load 指要移动的负载，这里就是重木头。","kind":"meaning","id":"u6-world-q1"},{"prompt":"“It lands on water. That is why it has no wheels.” 哪个是原因？","options":["没有轮子","它降落在水面上","有人饿了"],"answer":1,"why":"That is why 后引出结果；前面的降落地点是原因。","kind":"phonics","id":"u6-ph-q0"}]},{"id":7,"title":"This is Houston","zh":"这里是休斯敦","start":82,"end":93,"icon":"🌙","goal":"用 -ing 讲活动，转述别人说的话，并区分科幻故事与科学说明。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":125,"vocab":[{"word":"countdown clock","zh":"倒计时钟","example":"The countdown clock shows ten seconds."},{"word":"lunar module","zh":"登月舱","example":"The model lunar module is small."},{"word":"space capsule","zh":"太空舱","example":"The astronaut sits in the space capsule."},{"word":"spacesuit","zh":"宇航服","example":"The spacesuit protects the astronaut."},{"word":"launch pad","zh":"发射台","example":"The rocket is on the launch pad."},{"word":"crater","zh":"陨石坑；环形山","example":"The photograph shows a crater on the moon."},{"word":"control panel","zh":"控制面板","example":"The engineer checks the control panel."},{"word":"screen","zh":"屏幕","example":"We can see the moon on the screen."},{"word":"headset","zh":"耳麦","example":"She listens through her headset."}],"grammar":[{"title":"-ing 活动作主语","rule":"动词 -ing 短语可以作主语，表示做某事这件活动。单项活动一般接 is；不能把主语只写成动词原形。","examples":[{"en":"Reading about space is exciting.","zh":"阅读太空知识很令人兴奋。"},{"en":"Working together is important.","zh":"合作很重要。"}],"questions":[{"prompt":"___ a spacesuit takes time.","options":["Put on","Putting on","Puts on"],"answer":1,"why":"活动短语作主语，用 Putting on。","kind":"grammar","id":"u7-g0-q0"},{"prompt":"Watching the stars ___ interesting.","options":["is","are","do"],"answer":0,"why":"Watching the stars 整体是一项活动，接 is。","kind":"grammar","id":"u7-g0-q1"}]},{"title":"转述：said that …","rule":"本单元练习把原话改成过去时转述：I am → he / she was，I like → he / she liked；同时调整人称。","examples":[{"en":"“I am tired.” She said that she was tired.","zh":"“我累了。”她说她累了。"},{"en":"“I like science.” He said that he liked science.","zh":"“我喜欢科学。”他说他喜欢科学。"}],"questions":[{"prompt":"Zanrok said, “I am from Alpha 346.” → He said that he ___ from Alpha 346.","options":["is yesterday","was","were"],"answer":1,"why":"按本单元的过去时转述练习，am 改 was。","kind":"grammar","id":"u7-g1-q0"},{"prompt":"“I like soup,” she said. → She said that ___ liked soup.","options":["I","you","she"],"answer":2,"why":"转述她的话，人称 I 改成 she。","kind":"grammar","id":"u7-g1-q1"}]}],"song":{"title":"Can you hear us?","page":84,"type":"song","task":["在第 84 页区分宇航员与 Ground Control 的台词。","找到一个 -ing 作主语的句子，说出它在评价哪项活动。","两人轮读通讯对话；不把歌曲中的虚构通讯当作真实航天操作。"]},"extra":[],"phonics":{"title":"/ʌ/：mum、son 与 lunch","note":"对应第 84 页。mum、son、honey 的拼写不同，但重读元音都有 /ʌ/。短促发音，不拖成 /ɑː/。","pairs":[{"a":"mum","b":"son"},{"a":"lunch","b":"honey"},{"a":"Gus","b":"plums"}],"page":84,"questions":[{"prompt":"哪个词和 mum 含有相同的 /ʌ/ 元音？","options":["moon","son","screen"],"answer":1,"why":"son 中的 o 读 /ʌ/，和 mum 的元音相同。","kind":"phonics","id":"u7-ph-q0"}]},"story":{"title":"Alex, the engineer","pages":[86,87],"kind":"依据课文的教学改写","summary":"虚构故事把孩子们带进登月控制室。工作人员突然睡着，Alex 帮助通讯；真相揭开后，大家向他道歉并致谢。","sentences":[{"en":"The friends are in a space control room, where security officers suspect them.","zh":"朋友们来到太空控制室，保安怀疑他们。","note":"suspect 表示怀疑；他们还没解释清自己的来历。","id":"u7-story-s0"},{"en":"Suddenly, the engineers and guards fall asleep at their desks.","zh":"突然，工程师和保安在桌旁睡着了。","note":"fall asleep 是开始睡着。","id":"u7-story-s1"},{"en":"Phoebe notices that they had all been drinking tea.","zh":"Phoebe 注意到他们之前都喝过茶。","note":"all 是寻找共同线索的重要词。","id":"u7-story-s2"},{"en":"She thinks something in the tea caused the strange sleep.","zh":"她认为茶里的某种东西造成了异常入睡。","note":"thinks 表示根据线索推断；此处是虚构情节。","id":"u7-story-s3"},{"en":"A voice in a headset asks Houston for help.","zh":"耳麦里传来一个声音，向休斯敦请求帮助。","note":"asks … for help 是向……求助。","id":"u7-story-s4"},{"en":"Phoebe recognises the voice as Neil Armstrong's in the story.","zh":"在故事中，Phoebe 认出那是 Neil Armstrong 的声音。","note":"历史人物被放入虚构冒险，不表示这些事件真的发生过。","id":"u7-story-s5"},{"en":"Alex sits at the control panel and talks to the astronauts.","zh":"Alex 坐到控制面板前，与宇航员通话。","note":"talks to 说明他在做什么。","id":"u7-story-s6"},{"en":"His instructions help the astronauts continue their return journey.","zh":"他的指示帮助宇航员继续返回的旅程。","note":"return journey 是返程。","id":"u7-story-s7"},{"en":"When the engineers wake up, they hear that Alex has helped.","zh":"工程师醒来后，听说 Alex 提供了帮助。","note":"when 引出场景变化。","id":"u7-story-s8"},{"en":"A security officer apologises and says they have found the real spy.","zh":"一名保安道歉，说他们找到了真正的间谍。","note":"apologises 是道歉，说明先前的怀疑有误。","id":"u7-story-s9"},{"en":"Alex says a computer simulation taught him what to do, and the gate appears.","zh":"Alex 说自己从模拟游戏中学过这些操作，然后光门出现了。","note":"这是故事设定；玩游戏不等于具备真实航天操作资格。","id":"u7-story-s10"}],"questions":[{"prompt":"Phoebe 发现了什么共同线索？","options":["大家之前都喝过茶。","大家都戴着海盗眼罩。","大家刚从泳池出来。"],"answer":0,"why":"all been drinking tea 把工作人员睡着的现象联系起来。","kind":"meaning","id":"u7-story-q0"},{"prompt":"保安后来为什么道歉？","options":["他忘了送生日礼物。","他先前怀疑孩子们，但真正的间谍另有其人。","他不喜欢月亮。"],"answer":1,"why":"故事结尾说已找到真正的间谍，并承认孩子们帮助了大家。","kind":"meaning","id":"u7-story-q1"}]},"reading":{"title":"Lost in space: a science-fiction story","pages":[89],"kind":"依据课文的教学改写","summary":"科幻故事先写两只猴子失联，再跳到遥远未来。人物通过雕像发现两段情节的联系，并表达歉意与友好。","sentences":[{"en":"The first part of this fictional story begins with two monkeys named Leo and Rosy.","zh":"这篇虚构故事第一部分介绍两只名叫 Leo 和 Rosy 的猴子。","note":"fictional 明确它不是一份真实航天史记录。","id":"u7-reading-s0"},{"en":"Scientists send them into space and listen to sounds from the capsule.","zh":"科学家把它们送进太空，收听太空舱传来的声音。","note":"from the capsule 指声音来自哪里。","id":"u7-reading-s1"},{"en":"At first, everything seems normal.","zh":"起初，一切看起来正常。","note":"seems 表示看起来。","id":"u7-reading-s2"},{"en":"On the third day, the scientists lose contact with the animals.","zh":"第三天，科学家与动物失去联系。","note":"lose contact 是失去联系。","id":"u7-reading-s3"},{"en":"The second part jumps forward eight hundred years.","zh":"第二部分把时间向前推进了八百年。","note":"第一部分设在 1957 年，第二部分设在 2757 年，都是故事时间。","id":"u7-reading-s4"},{"en":"Commander Cormack's spacecraft lands on Pluto and meets monkey-like beings.","zh":"Cormack 指挥官的飞船降落在冥王星，遇到像猴子的生物。","note":"冥王星属于矮行星；这里的生命情节是科幻想象。","id":"u7-reading-s5"},{"en":"A special microphone translates their languages so they can communicate.","zh":"一种特殊麦克风翻译双方语言，使他们能够交流。","note":"so 表示结果：翻译让沟通成为可能。","id":"u7-reading-s6"},{"en":"The chief takes the visitors to a temple with a statue of two monkeys.","zh":"首领带访客来到一座有两只猴子雕像的庙。","note":"statue 是雕像，成为连接两段故事的线索。","id":"u7-reading-s7"},{"en":"Cormack recognises Leo and Rosy and understands the connection.","zh":"Cormack 认出 Leo 和 Rosy，明白了两段故事的联系。","note":"connection 是联系，不是两个毫无关联的故事。","id":"u7-reading-s8"},{"en":"He apologises for the past treatment of animals and hopes for friendship.","zh":"他为过去对待动物的方式道歉，并期待建立友谊。","note":"apologises for 后接道歉的原因；主题是尊重与承担责任。","id":"u7-reading-s9"}],"questions":[{"prompt":"哪件物品让 Cormack 明白了过去与未来的联系？","options":["一只学校铃。","Leo 和 Rosy 的雕像。","一辆伦敦巴士。"],"answer":1,"why":"他认识两只猴子的形象，因此理解了两个故事部分的关联。","kind":"meaning","id":"u7-reading-q0"},{"prompt":"这个文本应该怎样分类？","options":["有真实动物居民的冥王星新闻。","可以照做的航天实验步骤。","包含时间跳跃的科幻故事。"],"answer":2,"why":"情节明确是 fiction，不能把幻想中的生活当作科学发现。","kind":"meaning","id":"u7-reading-q1"}]},"world":{"title":"The changing shape of the moon","pages":[90,91],"kind":"依据课文的教学改写","summary":"月亮反射阳光；我们看到的亮面随月球相对太阳与地球的位置而变化。分清“看起来的形状”和月亮本身的形状。","sentences":[{"en":"The moon does not make its own light.","zh":"月亮本身不发光。","note":"does not make 是关键否定。","id":"u7-world-s0"},{"en":"We see it because it reflects light from the sun.","zh":"我们能看见它，是因为它反射太阳光。","note":"reflects 表示反射。","id":"u7-world-s1"},{"en":"As the moon travels around Earth, our view of its lit half changes.","zh":"月亮绕地球运动时，我们看到的受光部分会改变。","note":"our view 强调从地球看到的样子。","id":"u7-world-s2"},{"en":"A thin crescent can grow into a half moon and then a full moon.","zh":"细细的月牙看起来会逐渐变成半月，再到满月。","note":"grow 在这里指可见亮面增大，不是月球变大。","id":"u7-world-s3"},{"en":"We call the growing visible part waxing.","zh":"我们把可见亮面逐渐增大的阶段叫盈月阶段。","note":"waxing 是逐渐变亮、变圆。","id":"u7-world-s4"},{"en":"After the full moon, the visible lit part becomes smaller.","zh":"满月之后，可见的亮面开始缩小。","note":"after 把月相按顺序连接。","id":"u7-world-s5"},{"en":"This shrinking stage is called waning.","zh":"这一逐渐缩小的阶段叫亏月阶段。","note":"waning 与 waxing 相对。","id":"u7-world-s6"},{"en":"The moon itself does not turn into a thin slice; its appearance changes.","zh":"月亮本身没有变成薄片，变化的是我们看到的样子。","note":"itself 与 appearance 区分物体和外观。","id":"u7-world-s7"}],"questions":[{"prompt":"月亮的光来自哪里？","options":["它自己像灯泡一样发光。","太阳光的反射。","海洋中的电灯。"],"answer":1,"why":"reflects light from the sun 是文本的直接证据。","kind":"meaning","id":"u7-world-q0"},{"prompt":"月牙变成满月说明什么？","options":["月亮本身从薄片长成圆球。","我们看到的受光部分发生变化。","月亮离开了太阳系。"],"answer":1,"why":"变化的是可见亮面的比例，月亮本身没有变形。","kind":"meaning","id":"u7-world-q1"}]},"create":{"title":"小调查：大家喜欢什么节目？","pages":[92,93],"tasks":["设计一个节目偏好问题，选择 3–4 个选项，只统计愿意参与的家人或同学。","把真实回答计数并画简单条形图；没有调查时明确标为示例数据。","用 -ing 作主语说一种活动，再用 said that 转述一个人的观点。"],"frame":"My question was …\nI asked … people.\n… people chose …\nWatching … is …\nOne person said that …\nThis chart shows …","model":"This is an example survey, not real data. I asked four imaginary viewers about programmes. Two chose documentaries, one chose cartoons, and one chose sports. Watching documentaries is interesting. One viewer said that she liked learning about animals.","success":"数字与图一致；区分真实调查和示例；能正确使用一个 -ing 主语和一个转述句。","teacher":"对应第 92 页电视调查与第 93 页表达观点；范文数据明确为虚构示例。"},"questions":[{"prompt":"___ a spacesuit takes time.","options":["Put on","Putting on","Puts on"],"answer":1,"why":"活动短语作主语，用 Putting on。","kind":"grammar","id":"u7-g0-q0"},{"prompt":"Watching the stars ___ interesting.","options":["is","are","do"],"answer":0,"why":"Watching the stars 整体是一项活动，接 is。","kind":"grammar","id":"u7-g0-q1"},{"prompt":"Zanrok said, “I am from Alpha 346.” → He said that he ___ from Alpha 346.","options":["is yesterday","was","were"],"answer":1,"why":"按本单元的过去时转述练习，am 改 was。","kind":"grammar","id":"u7-g1-q0"},{"prompt":"“I like soup,” she said. → She said that ___ liked soup.","options":["I","you","she"],"answer":2,"why":"转述她的话，人称 I 改成 she。","kind":"grammar","id":"u7-g1-q1"},{"prompt":"Phoebe 发现了什么共同线索？","options":["大家之前都喝过茶。","大家都戴着海盗眼罩。","大家刚从泳池出来。"],"answer":0,"why":"all been drinking tea 把工作人员睡着的现象联系起来。","kind":"meaning","id":"u7-story-q0"},{"prompt":"保安后来为什么道歉？","options":["他忘了送生日礼物。","他先前怀疑孩子们，但真正的间谍另有其人。","他不喜欢月亮。"],"answer":1,"why":"故事结尾说已找到真正的间谍，并承认孩子们帮助了大家。","kind":"meaning","id":"u7-story-q1"},{"prompt":"哪件物品让 Cormack 明白了过去与未来的联系？","options":["一只学校铃。","Leo 和 Rosy 的雕像。","一辆伦敦巴士。"],"answer":1,"why":"他认识两只猴子的形象，因此理解了两个故事部分的关联。","kind":"meaning","id":"u7-reading-q0"},{"prompt":"这个文本应该怎样分类？","options":["有真实动物居民的冥王星新闻。","可以照做的航天实验步骤。","包含时间跳跃的科幻故事。"],"answer":2,"why":"情节明确是 fiction，不能把幻想中的生活当作科学发现。","kind":"meaning","id":"u7-reading-q1"},{"prompt":"月亮的光来自哪里？","options":["它自己像灯泡一样发光。","太阳光的反射。","海洋中的电灯。"],"answer":1,"why":"reflects light from the sun 是文本的直接证据。","kind":"meaning","id":"u7-world-q0"},{"prompt":"月牙变成满月说明什么？","options":["月亮本身从薄片长成圆球。","我们看到的受光部分发生变化。","月亮离开了太阳系。"],"answer":1,"why":"变化的是可见亮面的比例，月亮本身没有变形。","kind":"meaning","id":"u7-world-q1"},{"prompt":"哪个词和 mum 含有相同的 /ʌ/ 元音？","options":["moon","son","screen"],"answer":1,"why":"son 中的 o 读 /ʌ/，和 mum 的元音相同。","kind":"phonics","id":"u7-ph-q0"}]},{"id":8,"title":"A cold place","zh":"冰雪世界","start":94,"end":105,"icon":"🧊","goal":"用附加问句核对信息，用 may / might 表达可能，理解救助与求助。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":126,"vocab":[{"word":"northern lights","zh":"北极光","example":"The picture shows the northern lights."},{"word":"iceberg","zh":"冰山","example":"Most of the iceberg is under water."},{"word":"seal","zh":"海豹","example":"The seal rests on the ice."},{"word":"seal pup","zh":"小海豹","example":"We watch the seal pup from a distance."},{"word":"ice floe","zh":"浮冰","example":"The ice floe moves on the sea."},{"word":"polar bear","zh":"北极熊","example":"The book has a photograph of a polar bear."},{"word":"polar bear cub","zh":"北极熊幼崽","example":"The polar bear cub stays near its mother."},{"word":"sledge","zh":"雪橇","example":"The sledge is beside the snowy hill."},{"word":"mittens","zh":"连指手套","example":"My mittens keep my hands warm."},{"word":"igloo","zh":"冰屋","example":"We drew an igloo in the snow scene."}],"grammar":[{"title":"附加问句：…, is it?","rule":"本单元以 be 动词练习：前肯定、后否定；前否定、后肯定。短问句的人称和 be 动词要与前面一致。","examples":[{"en":"It is cold, is it not?","zh":"天气很冷，是吗？"},{"en":"They are not ready, are they?","zh":"他们还没准备好，是吗？"}],"questions":[{"prompt":"It is cold here, ___?","options":["is it","isn’t it","does it"],"answer":1,"why":"前面肯定 is，后面用否定 isn’t it。","kind":"grammar","id":"u8-g0-q0"},{"prompt":"They are not penguins, ___?","options":["are they","aren’t they","is it"],"answer":0,"why":"前面否定 are not，后面用肯定 are they。","kind":"grammar","id":"u8-g0-q1"}]},{"title":"may / might：可能","rule":"may / might + 动词原形，表示不确定的可能；否定是 may not / might not。不要把“可能”读成“必定”。","examples":[{"en":"We might visit the museum tomorrow.","zh":"我们明天可能去博物馆。"},{"en":"The ice may melt in warmer weather.","zh":"天气变暖时冰可能融化。"}],"questions":[{"prompt":"We might ___ home early.","options":["going","went","go"],"answer":2,"why":"might 后使用原形 go。","kind":"grammar","id":"u8-g1-q0"},{"prompt":"“It may snow.” 的意思是？","options":["一定会下雪。","可能下雪。","已经下雪了。"],"answer":1,"why":"may 表示可能性，并不保证一定发生。","kind":"grammar","id":"u8-g1-q1"}]}],"song":{"title":"Checking information：核对计划","page":96,"type":"dialogue","task":["阅读第 96 页对话，说出 Mia 的计划和出现的问题。","找出核对信息的句子，模仿 Can I just check something?。","用 We might … 提出一个不需要雪的替代活动。"]},"extra":[],"phonics":{"title":"附加问句的停顿","note":"依据第 95–96 页对话新编。先读完整陈述，再短暂停顿读 isn’t it? / are they?。真正不确定时常用上扬语气询问。","pairs":[{"a":"It is cold,","b":"isn’t it?"},{"a":"They are not ready,","b":"are they?"},{"a":"You are coming,","b":"aren’t you?"}],"page":96,"questions":[{"prompt":"They are not ready, ___? 应怎样补全并读？","options":["are they","isn’t it","does she"],"answer":0,"why":"前面主语 they、be 动词 are 且是否定，后面用 are they。","kind":"phonics","id":"u8-ph-q0"}]},"story":{"title":"Rescuing the seal pups","pages":[98,99],"kind":"依据课文的教学改写","summary":"朋友们想保护小海豹，却因登上浮冰而陷入危险。直升机救起他们，他们向警方提供信息；现实中保护动物应求助专业人员。","sentences":[{"en":"The friends notice six seal pups resting on an ice floe.","zh":"朋友们注意到六只小海豹躺在浮冰上。","note":"notice 是注意到；ice floe 是在水上漂动的冰块。","id":"u8-story-s0"},{"en":"Phoebe knows about the animals from a documentary.","zh":"Phoebe 从一部纪录片中了解过这些动物。","note":"from 表示知识来源。","id":"u8-story-s1"},{"en":"She says they should not get too close because they might frighten the pups.","zh":"她说不应该靠得太近，因为可能吓到小海豹。","note":"might 表示可能；保护动物也包括不打扰它们。","id":"u8-story-s2"},{"en":"Two men arrive, and the children believe that the pups are in danger.","zh":"两个男人来了，孩子们认为小海豹面临危险。","note":"believe 描述人物根据现场作出的判断。","id":"u8-story-s3"},{"en":"The children go onto the ice to help, but the floe moves away from the land.","zh":"孩子们登上冰面想帮忙，可浮冰离岸漂走了。","note":"but 标明好意之后出现的新问题。","id":"u8-story-s4"},{"en":"Now they are stranded, and the sea is too cold to swim across.","zh":"现在他们被困住了，海水太冷，无法游回去。","note":"stranded 是被困；这是故事对危险的描写。","id":"u8-story-s5"},{"en":"Later, a helicopter crew sees them waving and rescues them.","zh":"后来，直升机人员看见他们挥手，把他们救了起来。","note":"crew 是执行任务的工作人员。","id":"u8-story-s6"},{"en":"The pilot explains that their action was dangerous and that they were lucky.","zh":"飞行员指出他们的行为很危险，他们获救很幸运。","note":"没有把成功获救写成冒险一定有好结果。","id":"u8-story-s7"},{"en":"The friends describe the two men and identify them in police photographs.","zh":"朋友们描述了那两个男人，并在警方照片中辨认他们。","note":"identify 是辨认，提供信息是他们能做的帮助。","id":"u8-story-s8"},{"en":"Finally, the yellow light returns, and the time travellers leave the icy place.","zh":"最后黄光再次出现，时间旅行者离开了冰雪之地。","note":"先说明获救与报告，再讲魔法结尾。","id":"u8-story-s9"}],"questions":[{"prompt":"小海豹获救的意愿为什么又变成了孩子们的危险？","options":["他们登上浮冰，冰离开岸边，自己被困。","他们在家看纪录片。","他们先向专家报告。"],"answer":0,"why":"故事显示“想帮忙”不等于行动安全，冰漂走是关键转折。","kind":"meaning","id":"u8-story-q0"},{"prompt":"回到安全地点后，孩子们怎样帮助警方？","options":["用魔法找到了所有海豹。","描述男子并辨认照片。","自己驾驶直升机。"],"answer":1,"why":"他们提供观察到的信息，没有独立执行专业救援。","kind":"meaning","id":"u8-story-q1"}]},"reading":{"title":"Scott’s Antarctic journey","pages":[101],"kind":"依据课文的教学改写","summary":"了解 Scott 探险队的目标、到达和艰难返程。以时间顺序阅读历史题材，同时认识勇气需要与准备、条件和安全判断结合。","sentences":[{"en":"Robert Falcon Scott led an expedition towards the South Pole.","zh":"Robert Falcon Scott 带领一支探险队前往南极点。","note":"led 是 lead 的过去式；expedition 是考察或探险队伍。","id":"u8-reading-s0"},{"en":"He hoped his team would be the first to reach it.","zh":"他希望自己的队伍第一个到达那里。","note":"hoped 表示愿望，尚不等于结果。","id":"u8-reading-s1"},{"en":"The team travelled across ice in extremely difficult weather.","zh":"队伍在极其恶劣的天气下穿越冰原。","note":"extremely difficult 强调环境困难。","id":"u8-reading-s2"},{"en":"Scott and four companions continued the final part of the journey on foot.","zh":"Scott 和四位同伴步行继续最后一段旅程。","note":"on foot 是步行。","id":"u8-reading-s3"},{"en":"They reached the South Pole in January 1912.","zh":"他们于 1912 年 1 月到达南极点。","note":"reached 后直接接地点，不加 to。","id":"u8-reading-s4"},{"en":"They found a Norwegian flag and learned that another team had arrived earlier.","zh":"他们发现挪威国旗，得知另一支队伍更早到了。","note":"earlier 是更早；这里不沿用旧文不准确的“只早几天”。","id":"u8-reading-s5"},{"en":"The return journey was long, and the conditions became very severe.","zh":"返回路途漫长，环境变得十分严酷。","note":"return journey 与出发时的目标不同。","id":"u8-reading-s6"},{"en":"Scott and his four companions died before they could return safely.","zh":"Scott 和四位同伴未能安全返回，全部遇难。","note":"客观了解悲剧，不把牺牲生命作为孩子模仿的目标。","id":"u8-reading-s7"},{"en":"The diary later found with the expedition helped people understand their experience.","zh":"后来找到的探险日记帮助人们了解这段经历。","note":"diary 是历史信息的一种来源。","id":"u8-reading-s8"}],"questions":[{"prompt":"Scott 的目标是否完全实现？","options":["是，他确认自己是第一个到达的人。","没有，他到达了南极点，但别人更早到达。","没有，他根本没有向南极出发。"],"answer":1,"why":"区分“到达南极点”与“第一个到达”这两个不同目标。","kind":"meaning","id":"u8-reading-q0"},{"prompt":"哪种资料帮助后来的人了解这次经历？","options":["一本日记。","一张未来城市广告。","一张海盗寻宝图。"],"answer":0,"why":"日记是文中提及的重要记录资料。","kind":"meaning","id":"u8-reading-q1"}]},"world":{"title":"Glaciers: moving ice","pages":[102,103],"kind":"依据课文的教学改写","summary":"冰川由长期积累、压实的雪形成，并会缓慢流动。用形成—移动—融化三步理解它与水的关系。","sentences":[{"en":"A glacier is a large mass of ice that moves slowly.","zh":"冰川是会缓慢移动的大块冰体。","note":"mass 在这里指一大片物质。","id":"u8-world-s0"},{"en":"It can form where snow builds up over many years.","zh":"它能在雪多年累积的地方形成。","note":"builds up 是逐渐堆积。","id":"u8-world-s1"},{"en":"New layers press down on older snow, helping it turn into dense ice.","zh":"新雪层压在旧雪上，使它逐渐变成致密的冰。","note":"layers 是层；dense 是紧密的。","id":"u8-world-s2"},{"en":"The weight of the ice causes it to flow gradually.","zh":"冰体自身的重量使它逐渐流动。","note":"gradually 是逐渐地，不是一下子滑走。","id":"u8-world-s3"},{"en":"Valley glaciers move through mountain valleys.","zh":"山谷冰川在山谷中移动。","note":"valley 对应本册后面的自然地形词汇。","id":"u8-world-s4"},{"en":"Ice sheets cover much larger areas of land.","zh":"冰盖覆盖面积更大的陆地。","note":"much larger 表示大得多。","id":"u8-world-s5"},{"en":"When parts of a glacier reach warmer conditions, ice can melt into water.","zh":"冰川的一部分遇到更温暖的条件时，冰可能融化成水。","note":"melt into water 是物态变化。","id":"u8-world-s6"},{"en":"Pieces that break away into the sea can become icebergs.","zh":"断裂后进入海中的冰块可能形成冰山。","note":"break away 是分离、断裂出去。","id":"u8-world-s7"},{"en":"Studying glaciers helps us understand stored fresh water and environmental change.","zh":"研究冰川有助于理解淡水储存与环境变化。","note":"不需要背旧版百分比，也能讲清基本关系。","id":"u8-world-s8"}],"questions":[{"prompt":"冰川中的冰主要怎样形成？","options":["多年积雪逐渐压实成冰。","岩石瞬间变成水蒸气。","每一块冰都来自人工冰箱。"],"answer":0,"why":"关键词是 over many years、layers、press down。","kind":"meaning","id":"u8-world-q0"},{"prompt":"冰山可能怎样形成？","options":["沙子被风吹到树上。","冰川的一部分断裂进入海中。","海水中的所有鱼一起冻结。"],"answer":1,"why":"break away into the sea 描述冰山形成的一种过程。","kind":"meaning","id":"u8-world-q1"}]},"create":{"title":"旅行计划还没定","pages":[104,105],"tasks":["选一个假想的寒冷地区旅行，列出地点、同行人、交通和活动。","把尚未确定的项目用 may / might 表达，并说明一个影响因素。","与伙伴做计划核对对话，再用一句话说明现实中会向谁获取可靠帮助。"],"frame":"We may go to …\nWe might travel by …\nIt depends on …\nYou are going with …, aren’t you?\nWe have not decided yet.\nWe will ask … for advice.","model":"We might visit a snowy town during the holidays. We may travel by train, but we have not decided yet. It depends on the weather and our family’s plans. We might visit a museum if the weather is bad. We will ask a local guide about suitable activities.","success":"至少两处可能性表达；一个正确的附加问句；不把不确定计划说成已确定事实。","teacher":"对应第 104 页不确定假期计划角色卡；第 105 页影视评论可作延伸任务。"},"questions":[{"prompt":"It is cold here, ___?","options":["is it","isn’t it","does it"],"answer":1,"why":"前面肯定 is，后面用否定 isn’t it。","kind":"grammar","id":"u8-g0-q0"},{"prompt":"They are not penguins, ___?","options":["are they","aren’t they","is it"],"answer":0,"why":"前面否定 are not，后面用肯定 are they。","kind":"grammar","id":"u8-g0-q1"},{"prompt":"We might ___ home early.","options":["going","went","go"],"answer":2,"why":"might 后使用原形 go。","kind":"grammar","id":"u8-g1-q0"},{"prompt":"“It may snow.” 的意思是？","options":["一定会下雪。","可能下雪。","已经下雪了。"],"answer":1,"why":"may 表示可能性，并不保证一定发生。","kind":"grammar","id":"u8-g1-q1"},{"prompt":"小海豹获救的意愿为什么又变成了孩子们的危险？","options":["他们登上浮冰，冰离开岸边，自己被困。","他们在家看纪录片。","他们先向专家报告。"],"answer":0,"why":"故事显示“想帮忙”不等于行动安全，冰漂走是关键转折。","kind":"meaning","id":"u8-story-q0"},{"prompt":"回到安全地点后，孩子们怎样帮助警方？","options":["用魔法找到了所有海豹。","描述男子并辨认照片。","自己驾驶直升机。"],"answer":1,"why":"他们提供观察到的信息，没有独立执行专业救援。","kind":"meaning","id":"u8-story-q1"},{"prompt":"Scott 的目标是否完全实现？","options":["是，他确认自己是第一个到达的人。","没有，他到达了南极点，但别人更早到达。","没有，他根本没有向南极出发。"],"answer":1,"why":"区分“到达南极点”与“第一个到达”这两个不同目标。","kind":"meaning","id":"u8-reading-q0"},{"prompt":"哪种资料帮助后来的人了解这次经历？","options":["一本日记。","一张未来城市广告。","一张海盗寻宝图。"],"answer":0,"why":"日记是文中提及的重要记录资料。","kind":"meaning","id":"u8-reading-q1"},{"prompt":"冰川中的冰主要怎样形成？","options":["多年积雪逐渐压实成冰。","岩石瞬间变成水蒸气。","每一块冰都来自人工冰箱。"],"answer":0,"why":"关键词是 over many years、layers、press down。","kind":"meaning","id":"u8-world-q0"},{"prompt":"冰山可能怎样形成？","options":["沙子被风吹到树上。","冰川的一部分断裂进入海中。","海水中的所有鱼一起冻结。"],"answer":1,"why":"break away into the sea 描述冰山形成的一种过程。","kind":"meaning","id":"u8-world-q1"},{"prompt":"They are not ready, ___? 应怎样补全并读？","options":["are they","isn’t it","does she"],"answer":0,"why":"前面主语 they、be 动词 are 且是否定，后面用 are they。","kind":"phonics","id":"u8-ph-q0"}]},{"id":9,"title":"The Jurassic Age","zh":"恐龙时代","start":106,"end":117,"icon":"🦖","goal":"用假设句表达想象，梳理整册故事结尾，并用化石证据解释过去。","teacher":"未提供第六册教师用书；依据学生用书编写","grammarPage":127,"vocab":[{"word":"sunrise","zh":"日出","example":"We watched the sunrise from the window."},{"word":"horizon","zh":"地平线","example":"The sun appeared above the horizon."},{"word":"valley","zh":"山谷","example":"A river runs through the valley."},{"word":"pond","zh":"池塘","example":"Dragonflies fly above the pond."},{"word":"grassland","zh":"草原；草地","example":"The picture shows a wide grassland."},{"word":"stream","zh":"小溪","example":"The stream flows past the trees."},{"word":"bush","zh":"灌木丛","example":"A bird is hiding in the bush."},{"word":"swamp","zh":"沼泽","example":"The old story begins near a swamp."},{"word":"log","zh":"原木；倒下的树干","example":"The beetle is under the log."}],"grammar":[{"title":"If …, would … ：想象的情况","rule":"If + 主语 + 过去式，主句用 would / ’d + 原形。本单元表达现在或将来的假设，不等于事情真的发生过。","examples":[{"en":"If I had a time machine, I would visit the past.","zh":"如果我有时光机，我会去过去。"},{"en":"If I were a scientist, I would study fossils.","zh":"如果我是科学家，我会研究化石。"}],"questions":[{"prompt":"If I ___ a time machine, I would visit the future.","options":["have","had","will have"],"answer":1,"why":"第二条件句的 if 从句用过去式 had。","kind":"grammar","id":"u9-g0-q0"},{"prompt":"If I saw a dinosaur, I ___ take a photo from far away.","options":["would","was","did"],"answer":0,"why":"假设的结果使用 would + 原形。","kind":"grammar","id":"u9-g0-q1"}]},{"title":"What would you do if … ?","rule":"提问假设：疑问词 + would + 主语 + 原形 + if + 过去式？回答可用 I would … / I would not …。","examples":[{"en":"What would you do if you found a fossil?","zh":"如果你发现化石，会怎么做？"},{"en":"I would ask an expert about it.","zh":"我会请教专家。"}],"questions":[{"prompt":"What would you ___ if you met an alien?","options":["did","doing","do"],"answer":2,"why":"would 后用原形 do。","kind":"grammar","id":"u9-g1-q0"},{"prompt":"“I would not touch it.” 的缩写是？","options":["I wouldn’t touch it.","I didn’t touch it.","I haven’t touch it."],"answer":0,"why":"would not 缩写为 wouldn’t，含义保持假设。","kind":"grammar","id":"u9-g1-q1"}]}],"song":{"title":"I’d like to be …","page":108,"type":"song","task":["在第 108 页找到描述动物身体的词，如 horns、claws、wings。","选择一句 If I were …，只用朗读或画画表现想象，不模仿危险行为。","编一句善意的新歌词：If I were …, I would …。"]},"extra":[],"phonics":{"title":"/ɔː/：不同拼写的长元音","note":"对应第 108 页，采用教材英式发音示例。or、aw 等拼写可发 /ɔː/；口形略圆，声音拉长。不同口音可能有差别。","pairs":[{"a":"short","b":"claws"},{"a":"horns","b":"roar"},{"a":"more","b":"saw"}],"page":108,"questions":[{"prompt":"在教材的英式发音中，哪个词与 short 含相同的长元音 /ɔː/？","options":["claws","cat","sit"],"answer":0,"why":"short 和 claws 的重读元音都是 /ɔː/。","kind":"phonics","id":"u9-ph-q0"}]},"story":{"title":"The chase","pages":[110,111],"kind":"依据课文的教学改写","summary":"恐龙追逐把冒险推向结尾。孩子们回到科学课，似乎不记得经历，Patrick 口袋里的手镯却留下了证据。","sentences":[{"en":"The friends see a huge triceratops eating plants near some bushes.","zh":"朋友们看到一只巨大的三角龙在灌木附近吃植物。","note":"triceratops 是三角龙；故事把动物安排在幻想场景中。","id":"u9-story-s0"},{"en":"Alex wants to move closer because he knows it is a herbivore.","zh":"Alex 想靠近，因为他知道它是食草动物。","note":"herbivore 是食草动物，但不表示可以安全靠近野生动物。","id":"u9-story-s1"},{"en":"Phoebe warns that even a plant-eater can be frightened.","zh":"Phoebe 提醒说，食草动物也会受惊。","note":"even 强调“即使如此也会”。","id":"u9-story-s2"},{"en":"Small dinosaurs with sharp teeth come out and surround Alex.","zh":"一些有尖牙的小恐龙走出来，围住了 Alex。","note":"surround 是包围。","id":"u9-story-s3"},{"en":"A much larger Tyrannosaurus rex appears, and the smaller animals scatter.","zh":"一只大得多的霸王龙出现，小动物们四散逃开。","note":"scatter 是向各处散开。","id":"u9-story-s4"},{"en":"The friends run, but the large predator chases them.","zh":"朋友们跑起来，可大型捕食者追着他们。","note":"predator 是捕食者；but 表示困难没有解决。","id":"u9-story-s5"},{"en":"A giant pterosaur picks them up and carries them towards its nest.","zh":"一只巨大的翼龙抓起他们，带往自己的巢。","note":"翼龙是飞行爬行动物；这段不是准确的恐龙年代分类课。","id":"u9-story-s6"},{"en":"As it drops them above the nest, the yellow light appears.","zh":"当翼龙在巢上方松开他们时，黄光出现了。","note":"as 表示两个动作同时发生。","id":"u9-story-s7"},{"en":"The children land back in Mr Davis's classroom.","zh":"孩子们回到了 Davis 老师的教室。","note":"back 与开篇的科学课形成首尾呼应。","id":"u9-story-s8"},{"en":"He says they vanished for only a second or two after the explosion.","zh":"他说爆炸后他们只消失了一两秒钟。","note":"only 强调教室时间与冒险经历的反差。","id":"u9-story-s9"},{"en":"The friends seem to remember nothing, but Patrick finds an old bracelet in his pocket.","zh":"朋友们似乎什么都不记得，Patrick 却从口袋里找到一只旧手镯。","note":"bracelet 回扣伦敦大火中获得的礼物，留下悬念。","id":"u9-story-s10"}],"questions":[{"prompt":"结尾哪件物品把故事与伦敦大火一集联系起来？","options":["旧手镯。","学校垃圾桶。","未来列车票。"],"answer":0,"why":"手镯是获救小孩的母亲送给 Patrick 的。","kind":"meaning","id":"u9-story-q0"},{"prompt":"结尾为什么让人产生悬念？","options":["老师说他们离开了十年。","他们似乎忘了冒险，却有手镯这样的线索。","所有人物都变成了海盗。"],"answer":1,"why":"记忆与实物证据形成反差，读者会继续思考冒险是否真的发生。","kind":"meaning","id":"u9-story-q1"}]},"reading":{"title":"Life around a pond","pages":[112,113],"kind":"依据课文的教学改写","summary":"池塘周围的动物各有外形与行为特征。读描述时用“它是什么—长什么样—怎样生活”来整理信息。","sentences":[{"en":"A pond and its edges can be home to many kinds of wildlife.","zh":"池塘及周围可以成为许多野生生物的家园。","note":"be home to 表示是……的栖息地。","id":"u9-reading-s0"},{"en":"The article describes birds, mammals, insects and small fish.","zh":"文章介绍鸟类、哺乳动物、昆虫和小鱼。","note":"先分大类，再记具体特征。","id":"u9-reading-s1"},{"en":"A male mallard is easy to recognise by its green head.","zh":"雄性绿头鸭的绿色头部容易辨认。","note":"male 指雄性；并不是所有鸭子都有绿色头。","id":"u9-reading-s2"},{"en":"Newts are amphibians with long tails and live near water.","zh":"蝾螈是有长尾巴、在水边生活的两栖动物。","note":"amphibians 是两栖动物这一大类。","id":"u9-reading-s3"},{"en":"A kingfisher may appear as a quick flash of blue before flying away.","zh":"翠鸟飞走之前，可能只让人看到一道快速的蓝色身影。","note":"a flash of blue 是形象描写，不是闪光灯。","id":"u9-reading-s4"},{"en":"A heron waits patiently and uses its long beak to catch food.","zh":"苍鹭耐心等待，用长喙捕食。","note":"patiently 是耐心地，描述行为方式。","id":"u9-reading-s5"},{"en":"Water voles live near the banks and eat grass and other plants.","zh":"水䶄生活在岸边，吃草和其他植物。","note":"water vole 是水䶄，一种啮齿动物，不必误认成普通家鼠。","id":"u9-reading-s6"},{"en":"Dragonflies have four wings and can be seen flying above the water.","zh":"蜻蜓有四片翅膀，可以在水面上方看到它们飞行。","note":"four wings 是用于辨认的特征。","id":"u9-reading-s7"},{"en":"Quiet observation helps us notice differences without disturbing the animals.","zh":"安静观察帮助我们发现差别，同时不打扰动物。","note":"without disturbing 表示避免干扰；不需要靠近水边或捕捉动物。","id":"u9-reading-s8"}],"questions":[{"prompt":"哪种动物在文中以四片翅膀为特征？","options":["蜻蜓。","苍鹭。","水䶄。"],"answer":0,"why":"Dragonflies 对应 four wings，是直接的外形信息。","kind":"meaning","id":"u9-reading-q0"},{"prompt":"哪一种整理方式最能帮助读懂这篇说明文？","options":["只数逗号。","动物名称、外形特征、行为或食物。","把全部动物都写成鱼。"],"answer":1,"why":"文本通过特征和行为区分不同动物，分类记录最有效。","kind":"meaning","id":"u9-reading-q1"}]},"world":{"title":"Fossils: evidence from the past","pages":[114,115],"kind":"依据课文的教学改写","summary":"化石是古代生物遗骸或活动痕迹的保存记录。通过埋藏、保存、发现和研究，理解科学家怎样从证据认识过去。","sentences":[{"en":"Fossils are preserved remains or traces of life from the past.","zh":"化石是过去生物遗骸或活动痕迹保存下来的记录。","note":"remains 是遗骸，traces 包括足迹等活动痕迹。","id":"u9-world-s0"},{"en":"They can include bones, shells, teeth and footprints.","zh":"它们可以包括骨骼、贝壳、牙齿和足迹。","note":"include 表示列举，化石不只有恐龙骨头。","id":"u9-world-s1"},{"en":"An animal may be buried in mud or other sediment after it dies.","zh":"动物死后，可能被泥或其他沉积物掩埋。","note":"may 表示一种可能过程，并非每个动物都会形成化石。","id":"u9-world-s2"},{"en":"Over a long time, some hard parts or their shapes can be preserved.","zh":"经过很长时间，一些坚硬部分或其形状可能保存下来。","note":"preserved 是被保存；强调长时间与条件。","id":"u9-world-s3"},{"en":"The surrounding layers can become rock.","zh":"周围的沉积层可能变成岩石。","note":"layers 把过程与地层联系起来。","id":"u9-world-s4"},{"en":"Palaeontologists study fossils to learn about ancient life.","zh":"古生物学家研究化石，以了解古代生命。","note":"palaeontologists 可分块练读，先理解“研究古生物的人”。","id":"u9-world-s5"},{"en":"They record where a fossil was found and examine it carefully.","zh":"他们记录化石的发现地点，并仔细检查。","note":"where 引出证据的位置信息。","id":"u9-world-s6"},{"en":"Some fossils are prepared for museum displays so other people can learn from them.","zh":"一些化石会被整理用于博物馆展示，让更多人学习。","note":"displays 是展览；整理与研究需要专业人员。","id":"u9-world-s7"},{"en":"A model imprint made in clay is useful for learning, but it is not an ancient fossil.","zh":"在黏土里制作的印痕模型有助于学习，但并不是真正的古代化石。","note":"model 与 fossil 分开，避免把课堂手工当作自然证据。","id":"u9-world-s8"}],"questions":[{"prompt":"哪一项也可以成为化石记录？","options":["古代生物留下并保存下来的足迹。","今天刚写完的购物单。","任何刚掉下来的树叶都自动是化石。"],"answer":0,"why":"化石可以是遗骸，也可以是经过保存的活动痕迹。","kind":"meaning","id":"u9-world-q0"},{"prompt":"自己做的黏土印痕与真正化石有什么关系？","options":["它是教学模型，不是古代自然形成的化石。","它立刻有几千万年历史。","它能证明任何恐龙都生活在同一时代。"],"answer":0,"why":"模型用来帮助理解过程，不等于真实的古代证据。","kind":"meaning","id":"u9-world-q1"}]},"create":{"title":"我的证据海报与假设故事","pages":[116,117],"tasks":["从课内已核对的内容选一只动物或一种化石，画大图并列 3 个要点。","用 I know … because … 说明一个有证据的判断；不了解的信息写“尚不确定”。","再用 If I …, I would … 创作 2 句想象，与事实部分分开展示。"],"frame":"My topic is …\nHere are three things I learned: …\nMy evidence comes from page …\nI am not sure about …\nIf I found …, I would …","model":"My topic is fossils. Fossils can be remains or traces of ancient life. They may include shells, bones or footprints. Scientists study them carefully. I learned this from the fossil pages in my book. If I found an unusual stone, I would photograph it and ask an expert about it.","success":"海报内容有来源，能分清事实、尚不确定的信息和假设；至少正确使用一个第二条件句。","teacher":"对应第 116 页海报展示；第 117 页藏头诗可作为可选创作。未给出没有原音就无法核实的恐龙海报听力填空答案。"},"questions":[{"prompt":"If I ___ a time machine, I would visit the future.","options":["have","had","will have"],"answer":1,"why":"第二条件句的 if 从句用过去式 had。","kind":"grammar","id":"u9-g0-q0"},{"prompt":"If I saw a dinosaur, I ___ take a photo from far away.","options":["would","was","did"],"answer":0,"why":"假设的结果使用 would + 原形。","kind":"grammar","id":"u9-g0-q1"},{"prompt":"What would you ___ if you met an alien?","options":["did","doing","do"],"answer":2,"why":"would 后用原形 do。","kind":"grammar","id":"u9-g1-q0"},{"prompt":"“I would not touch it.” 的缩写是？","options":["I wouldn’t touch it.","I didn’t touch it.","I haven’t touch it."],"answer":0,"why":"would not 缩写为 wouldn’t，含义保持假设。","kind":"grammar","id":"u9-g1-q1"},{"prompt":"结尾哪件物品把故事与伦敦大火一集联系起来？","options":["旧手镯。","学校垃圾桶。","未来列车票。"],"answer":0,"why":"手镯是获救小孩的母亲送给 Patrick 的。","kind":"meaning","id":"u9-story-q0"},{"prompt":"结尾为什么让人产生悬念？","options":["老师说他们离开了十年。","他们似乎忘了冒险，却有手镯这样的线索。","所有人物都变成了海盗。"],"answer":1,"why":"记忆与实物证据形成反差，读者会继续思考冒险是否真的发生。","kind":"meaning","id":"u9-story-q1"},{"prompt":"哪种动物在文中以四片翅膀为特征？","options":["蜻蜓。","苍鹭。","水䶄。"],"answer":0,"why":"Dragonflies 对应 four wings，是直接的外形信息。","kind":"meaning","id":"u9-reading-q0"},{"prompt":"哪一种整理方式最能帮助读懂这篇说明文？","options":["只数逗号。","动物名称、外形特征、行为或食物。","把全部动物都写成鱼。"],"answer":1,"why":"文本通过特征和行为区分不同动物，分类记录最有效。","kind":"meaning","id":"u9-reading-q1"},{"prompt":"哪一项也可以成为化石记录？","options":["古代生物留下并保存下来的足迹。","今天刚写完的购物单。","任何刚掉下来的树叶都自动是化石。"],"answer":0,"why":"化石可以是遗骸，也可以是经过保存的活动痕迹。","kind":"meaning","id":"u9-world-q0"},{"prompt":"自己做的黏土印痕与真正化石有什么关系？","options":["它是教学模型，不是古代自然形成的化石。","它立刻有几千万年历史。","它能证明任何恐龙都生活在同一时代。"],"answer":0,"why":"模型用来帮助理解过程，不等于真实的古代证据。","kind":"meaning","id":"u9-world-q1"},{"prompt":"在教材的英式发音中，哪个词与 short 含相同的长元音 /ɔː/？","options":["claws","cat","sit"],"answer":0,"why":"short 和 claws 的重读元音都是 /ɔː/。","kind":"phonics","id":"u9-ph-q0"}]}],"glossary":[{"word":"Alex","zh":"Alex：时间旅行者之一，戴眼镜的男孩"},{"word":"Phoebe","zh":"Phoebe：时间旅行者之一，善于观察和判断地点"},{"word":"Patrick","zh":"Patrick：时间旅行者之一，经常行动很快"},{"word":"Mr Davis","zh":"Davis 老师：孩子们的科学老师"},{"word":"experiment","zh":"实验"},{"word":"powder","zh":"粉末"},{"word":"mixture","zh":"混合物"},{"word":"goggles","zh":"护目镜"},{"word":"explosion","zh":"爆炸"},{"word":"instructions","zh":"说明；指示"},{"word":"accident","zh":"事故；意外"},{"word":"already","zh":"已经"},{"word":"yet","zh":"还；已经（常见于否定或问句）"},{"word":"episode","zh":"一集；一个故事篇章"},{"word":"treasure","zh":"宝藏；珍爱的东西"},{"word":"pirate","zh":"海盗"},{"word":"prisoner","zh":"被关押的人"},{"word":"sneeze","zh":"打喷嚏"},{"word":"helmet","zh":"头盔"},{"word":"copper","zh":"铜"},{"word":"parade","zh":"游行；阅兵"},{"word":"inn","zh":"客栈"},{"word":"blurb","zh":"书的简短介绍"},{"word":"review","zh":"评论"},{"word":"biography","zh":"传记"},{"word":"unicycle","zh":"独轮车；第 22 页补充词"},{"word":"inline skates","zh":"直排轮滑鞋；第 22 页补充词"},{"word":"impatient","zh":"不耐烦的；心急的"},{"word":"emergency","zh":"紧急情况"},{"word":"passenger","zh":"乘客"},{"word":"destination","zh":"目的地"},{"word":"prediction","zh":"预测"},{"word":"pollution","zh":"污染"},{"word":"Rhodopis","zh":"Rhodopis：传说中的女孩"},{"word":"symbol","zh":"符号"},{"word":"servant","zh":"仆人"},{"word":"scorpion","zh":"蝎子"},{"word":"corridor","zh":"走廊"},{"word":"cube","zh":"正方体"},{"word":"cylinder","zh":"圆柱"},{"word":"vertex","zh":"顶点"},{"word":"edge","zh":"棱；边缘"},{"word":"face","zh":"面；脸"},{"word":"net","zh":"网；几何图形的展开图"},{"word":"cheer","zh":"欢呼"},{"word":"rower","zh":"赛艇选手"},{"word":"sore","zh":"疼痛的"},{"word":"muscle","zh":"肌肉"},{"word":"voluntary","zh":"随意的；能有意识控制的"},{"word":"involuntary","zh":"不随意的；不需要有意识决定的"},{"word":"skeleton","zh":"骨骼；骨架"},{"word":"energy","zh":"能量"},{"word":"Mr Fisher","zh":"Fisher 先生：伦敦大火故事中的人物"},{"word":"bracelet","zh":"手镯"},{"word":"belongings","zh":"个人物品"},{"word":"furniture","zh":"家具"},{"word":"wax","zh":"蜡"},{"word":"raven","zh":"渡鸦"},{"word":"impressionism","zh":"印象派"},{"word":"brush stroke","zh":"笔触"},{"word":"Professor Potts","zh":"Potts 教授：虚构的发明家"},{"word":"nails","zh":"钉子；第 70 页补充词"},{"word":"paint pot","zh":"颜料罐；第 70 页补充词"},{"word":"invention","zh":"发明"},{"word":"pivot","zh":"支点"},{"word":"load","zh":"负载；要移动的物体"},{"word":"force","zh":"力"},{"word":"purpose","zh":"用途；目的"},{"word":"reliable","zh":"可靠的"},{"word":"Houston","zh":"休斯敦：故事中的航天控制中心所在地"},{"word":"astronaut","zh":"宇航员"},{"word":"engineer","zh":"工程师"},{"word":"simulation","zh":"模拟"},{"word":"spy","zh":"间谍"},{"word":"apologise","zh":"道歉"},{"word":"Pluto","zh":"冥王星，属于矮行星"},{"word":"reflect","zh":"反射"},{"word":"crescent","zh":"月牙；新月形"},{"word":"waxing","zh":"月亮可见亮面逐渐增大"},{"word":"waning","zh":"月亮可见亮面逐渐减小"},{"word":"documentary","zh":"纪录片"},{"word":"stranded","zh":"被困住；无法离开"},{"word":"rescue","zh":"救援"},{"word":"expedition","zh":"考察；探险"},{"word":"companion","zh":"同伴"},{"word":"glacier","zh":"冰川"},{"word":"ice sheet","zh":"冰盖"},{"word":"melt","zh":"融化"},{"word":"climate","zh":"气候"},{"word":"triceratops","zh":"三角龙"},{"word":"Tyrannosaurus rex","zh":"霸王龙"},{"word":"pterosaur","zh":"翼龙；飞行爬行动物"},{"word":"herbivore","zh":"食草动物"},{"word":"predator","zh":"捕食者"},{"word":"nest","zh":"巢"},{"word":"mallard","zh":"绿头鸭"},{"word":"newt","zh":"蝾螈"},{"word":"kingfisher","zh":"翠鸟"},{"word":"heron","zh":"苍鹭"},{"word":"water vole","zh":"水䶄；一种在水边生活的啮齿动物"},{"word":"dragonfly","zh":"蜻蜓"},{"word":"fossil","zh":"化石"},{"word":"palaeontologist","zh":"古生物学家"},{"word":"sediment","zh":"沉积物"},{"word":"evidence","zh":"证据"},{"word":"trace","zh":"痕迹"},{"word":"preserve","zh":"保存"}],"coverageNote":"10 个单元、80 个学习模块：课文词汇选读、双语语法、故事改写、主题阅读、发音或功能语块、跨学科理解、表达任务、综合挑战。第 2、4、6、8 单元的教材为功能对话，本站如实标注；其语音练习是教学新编。含逐页原书对照，不冒充原版录音或教师答案。","shortLabel":"让英语成为表达的工具","storyHint":"跟着伙伴穿越时空","version":2,"storageKey":"storysprout:super-minds-6-v2","draftMin":15,"audioNote":"电脑语音合成，不是教材 CD 原声；录音回听与朗读打卡不提供自动发音评分。"};
